/* DAWAH X — ahmad, অধ্যায় 18 · খণ্ড 18 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][18]=[[3401,3401,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي الْكَنُودِ ‏ ‏أَصَبْتُ خَاتَمًا يَوْمًا فَذَكَرَهُ فَرَآهُ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏فِي يَدِهِ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ حَلَقَةِ الذَّهَبِ ‏","","",""],[3402,3402,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْمَرٍ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏انْشَقَّ ‏ ‏الْقَمَرُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شِقَّتَيْنِ ‏ ‏حَتَّى نَظَرُوا إِلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْهَدُوا ‏","","",""],[3403,3403,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْمَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحَوْلَ ‏ ‏الْكَعْبَةِ ‏ ‏سِتُّونَ وَثَلَاثُ مِائَةِ ‏ ‏نُصُبٍ ‏ ‏فَجَعَلَ يَطْعُنُهَا بِعُودٍ كَانَ بِيَدِهِ وَيَقُولُ ‏ { ‏جَاءَ الْحَقُّ وَمَا ‏ ‏يُبْدِئُ ‏ ‏الْبَاطِلُ وَمَا يُعِيدُ ‏} { ‏جَاءَ الْحَقُّ ‏ ‏وَزَهَقَ ‏ ‏الْبَاطِلُ إِنَّ الْبَاطِلَ كَانَ ‏ ‏زَهُوقًا ‏ }","","",""],[3404,3404,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏وَلَيْسَ مِنْهَا مَنْ يَقْدُمُهَا وَقُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏يَحْيَى الْجَابِرَ ‏ ‏عَنْ ‏ ‏أَبِي مَاجِدٍ الْحَنَفِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ السَّيْرِ بِالْجِنَازَةِ فَقَالَ ‏ ‏مَتْبُوعَةٌ وَلَيْسَتْ بِتَابِعَةٍ ‏","","",""],[3405,3405,"","","‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًى ‏ ‏قَالَ ‏ ‏فَخَرَجَتْ عَلَيْنَا حَيَّةٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْتُلُوهَا ‏ ‏فَابْتَدَرْنَاهَا ‏ ‏فَسَبَقَتْنَا ‏","","",""],[3406,3406,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدِ اللَّهِ بْنِ إِدْرِيسَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَعْمَشَ ‏ ‏يَرْوِي عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَخْرُجُ إِلَيْنَا فَيَقُولُ إِنَّنِي لَأُخْبَرُ بِمَكَانِكُمْ وَمَا يَمْنَعُنِي أَنْ أَخْرُجَ إِلَيْكُمْ إِلَّا كَرَاهِيَةُ أَنْ أُمِلَّكُمْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَخَوَّلُنَا ‏ ‏بِالْمَوْعِظَةِ فِي الْأَيَّامِ كَرَاهِيَةَ ‏ ‏السَّآمَةِ ‏ ‏عَلَيْنَا ‏","","",""],[3407,3407,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏وَعَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏إِذَا رَكَعَ أَحَدُكُمْ فَلْيُفْرِشْ ذِرَاعَيْهِ فَخِذَيْهِ ‏ ‏وَلْيَجْنَأْ ‏ ‏ثُمَّ طَبَّقَ بَيْنَ كَفَّيْهِ فَكَأَنِّي أَنْظُرُ إِلَى ‏ ‏اخْتِلَافِ ‏ ‏أَصَابِعِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثُمَّ طَبَّقَ كَفَّيْهِ فَأَرَاهُمْ ‏","","",""],[3408,3408,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏الَّذِينَ آمَنُوا وَلَمْ ‏ ‏يَلْبِسُوا ‏ ‏إِيمَانَهُمْ بِظُلْمٍ ‏} ‏شَقَّ ‏ ‏ذَلِكَ عَلَى النَّاسِ وَقَالُوا يَا رَسُولَ اللَّهِ فَأَيُّنَا لَا يَظْلِمُ نَفْسَهُ قَالَ إِنَّهُ لَيْسَ الَّذِي تَعْنُونَ أَلَمْ تَسْمَعُوا مَا قَالَ الْعَبْدُ الصَّالِحُ ‏ { ‏يَا بُنَيَّ لَا تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ ‏} ‏إِنَّمَا هُوَ الشِّرْكُ ‏","","",""],[3409,3409,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏أَبَلَغَكَ أَنَّ اللَّهَ عَزَّ وَجَلَّ يَحْمِلُ الْخَلَائِقَ عَلَى أُصْبُعٍ وَالسَّمَوَاتِ عَلَى أُصْبُعٍ وَالْأَرَضِينَ عَلَى أُصْبُعٍ وَالشَّجَرَ عَلَى أُصْبُعٍ ‏ ‏وَالثَّرَى ‏ ‏عَلَى أُصْبُعٍ فَضَحِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏ ‏فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ ‏} ‏الْآيَةَ ‏","","",""],[3410,3410,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ قَرَأَ سُورَةَ ‏ ‏يُوسُفَ ‏ ‏بِحِمْصَ ‏ ‏فَقَالَ رَجُلٌ مَا هَكَذَا أُنْزِلَتْ فَدَنَا مِنْهُ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَوَجَدَ مِنْهُ رِيحَ الْخَمْرِ فَقَالَ أَتُكَذِّبُ بِالْحَقِّ وَتَشْرَبُ ‏ ‏الرِّجْسَ ‏ ‏لَا أَدَعُكَ حَتَّى أَجْلِدَكَ حَدًّا قَالَ فَضَرَبَهُ ‏ ‏الْحَدَّ ‏ ‏وَقَالَ ‏ ‏وَاللَّهِ لَهَكَذَا أَقْرَأَنِيهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[3411,3411,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَمْشِي مَعَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏بِمِنًى ‏ ‏فَلَقِيَهُ ‏ ‏عُثْمَانُ ‏ ‏فَقَامَ مَعَهُ يُحَدِّثُهُ فَقَالَ لَهُ ‏ ‏عُثْمَانُ ‏ ‏يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏أَلَا نُزَوِّجُكَ جَارِيَةً شَابَّةً لَعَلَّهَا أَنْ تُذَكِّرَكَ مَا مَضَى مِنْ زَمَانِكَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَمَا لَئِنْ قُلْتَ ذَاكَ لَقَدْ قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏مَعْشَرَ ‏ ‏الشَّبَابِ ‏ ‏مَنْ اسْتَطَاعَ مِنْكُمْ ‏ ‏الْبَاءَةَ ‏ ‏فَلْيَتَزَوَّجْ فَإِنَّهُ ‏ ‏أَغَضُّ ‏ ‏لِلْبَصَرِ ‏ ‏وَأَحْصَنُ ‏ ‏لِلْفَرْجِ وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ فَإِنَّهُ لَهُ ‏ ‏وِجَاءٌ ‏","","",""],[3412,3412,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ صَلَّى ‏ ‏عُثْمَانُ ‏ ‏بِمِنًى ‏ ‏أَرْبَعًا فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًى ‏ ‏رَكْعَتَيْنِ وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَكْعَتَيْنِ وَمَعَ ‏ ‏عُمَرَ ‏ ‏رَكْعَتَيْنِ ‏","","",""],[3413,3413,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ النَّاسِ قَرْنِي ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ يَأْتِي بَعْدَ ذَلِكَ قَوْمٌ تَسْبِقُ شَهَادَاتُهُمْ أَيْمَانَهُمْ وَأَيْمَانُهُمْ شَهَادَاتِهِمْ ‏","","",""],[3414,3414,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّنِي لَأَعْرِفُ آخِرَ أَهْلِ النَّارِ خُرُوجًا مِنْ النَّارِ رَجُلٌ يَخْرُجُ مِنْهَا زَحْفًا فَيُقَالُ لَهُ ‏ ‏انْطَلِقْ فَادْخُلْ الْجَنَّةَ قَالَ فَيَذْهَبُ يَدْخُلُ فَيَجِدُ النَّاسَ قَدْ أَخَذُوا الْمَنَازِلَ ‏ ‏قَالَ فَيَرْجِعُ فَيَقُولُ يَا رَبِّ قَدْ أَخَذَ النَّاسُ الْمَنَازِلَ قَالَ فَيُقَالُ لَهُ أَتَذْكُرُ الزَّمَانَ الَّذِي كُنْتَ فِيهِ قَالَ فَيَقُولُ نَعَمْ فَيُقَالُ لَهُ ‏ ‏تَمَنَّهْ ‏ ‏فَيَتَمَنَّى فَيُقَالُ إِنَّ لَكَ الَّذِي تَمَنَّيْتَ وَعَشَرَةَ أَضْعَافِ الدُّنْيَا قَالَ فَيَقُولُ أَتَسْخَرُ بِي وَأَنْتَ الْمَلِكُ قَالَ فَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحِكَ حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏","","",""],[3415,3415,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِذَا أَحْسَنْتُ فِي الْإِسْلَامِ أُؤَاخَذُ بِمَا عَمِلْتُ فِي الْجَاهِلِيَّةِ فَقَالَ ‏ ‏إِذَا أَحْسَنْتَ فِي الْإِسْلَامِ لَمْ تُؤَاخَذْ بِمَا عَمِلْتَ فِي الْجَاهِلِيَّةِ وَإِذَا أَسَأْتَ فِي الْإِسْلَامِ ‏ ‏أُخِذْتَ ‏ ‏بِالْأَوَّلِ وَالْآخِرِ ‏","","",""],[3416,3416,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ هُوَ فِيهَا فَاجِرٌ لِيَقْتَطِعَ بِهَا مَالَ امْرِئٍ مُسْلِمٍ لَقِيَ اللَّهَ عَزَّ وَجَلَّ وَهُوَ عَلَيْهِ غَضْبَانُ فَقَالَ ‏ ‏الْأَشْعَثُ ‏ ‏فِيَّ وَاللَّهِ كَانَ ذَلِكَ كَانَ بَيْنِي وَبَيْنَ رَجُلٍ مِنْ ‏ ‏الْيَهُودِ ‏ ‏أَرْضٌ ‏ ‏فَجَحَدَنِي ‏ ‏فَقَدَّمْتُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَكَ بَيِّنَةٌ قُلْتُ لَا فَقَالَ لِلْيَهُودِيِّ احْلِفْ فَقُلْتُ يَا رَسُولَ اللَّهِ إِذَنْ يَحْلِفَ فَيَذْهَبَ مَالِي فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا ‏} ‏إِلَى آخِرِ الْآيَةِ ‏","","",""],[3417,3417,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنِي ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏أَرْعَى غَنَمًا ‏ ‏لِعُقْبَةَ بْنِ أَبِي مُعَيْطٍ ‏ ‏فَمَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏فَقَالَ يَا غُلَامُ هَلْ مِنْ لَبَنٍ قَالَ قُلْتُ نَعَمْ وَلَكِنِّي مُؤْتَمَنٌ قَالَ فَهَلْ مِنْ شَاةٍ لَمْ ‏ ‏يَنْزُ ‏ ‏عَلَيْهَا ‏ ‏الْفَحْلُ ‏ ‏فَأَتَيْتُهُ بِشَاةٍ فَمَسَحَ ضَرْعَهَا فَنَزَلَ لَبَنٌ فَحَلَبَهُ فِي إِنَاءٍ فَشَرِبَ وَسَقَى ‏ ‏أَبَا بَكْرٍ ‏ ‏ثُمَّ قَالَ لِلضَّرْعِ ‏ ‏اقْلِصْ ‏ ‏فَقَلَصَ ‏ ‏قَالَ ثُمَّ أَتَيْتُهُ بَعْدَ هَذَا فَقُلْتُ يَا رَسُولَ اللَّهِ عَلِّمْنِي مِنْ هَذَا الْقَوْلِ قَالَ فَمَسَحَ رَأْسِي وَقَالَ يَرْحَمُكَ اللَّهُ فَإِنَّكَ ‏ ‏غُلَيِّمٌ مُعَلَّمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏بِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏فَأَتَاهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏بِصَخْرَةٍ مَنْقُورَةٍ فَاحْتَلَبَ فِيهَا فَشَرِبَ وَشَرِبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَشَرِبْتُ قَالَ ثُمَّ أَتَيْتُهُ بَعْدَ ذَلِكَ قُلْتُ عَلِّمْنِي مِنْ هَذَا الْقُرْآنِ قَالَ إِنَّكَ غُلَامٌ مُعَلَّمٌ قَالَ فَأَخَذْتُ مِنْ ‏ ‏فِيهِ سَبْعِينَ سُورَةً ‏","","",""],[3418,3418,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ نَظَرَ فِي قُلُوبِ الْعِبَادِ فَوَجَدَ قَلْبَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرَ قُلُوبِ الْعِبَادِ فَاصْطَفَاهُ لِنَفْسِهِ فَابْتَعَثَهُ بِرِسَالَتِهِ ثُمَّ نَظَرَ فِي قُلُوبِ الْعِبَادِ بَعْدَ قَلْبِ ‏ ‏مُحَمَّدٍ ‏ ‏فَوَجَدَ قُلُوبَ أَصْحَابِهِ خَيْرَ قُلُوبِ الْعِبَادِ فَجَعَلَهُمْ وُزَرَاءَ نَبِيِّهِ يُقَاتِلُونَ عَلَى دِينِهِ فَمَا رَأَى الْمُسْلِمُونَ حَسَنًا فَهُوَ عِنْدَ اللَّهِ حَسَنٌ وَمَا رَأَوْا سَيِّئًا فَهُوَ عِنْدَ اللَّهِ سَيِّئٌ ‏","","",""],[3419,3419,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَلَّكُمْ سَتُدْرِكُونَ أَقْوَامًا يُصَلُّونَ صَلَاةً لِغَيْرِ وَقْتِهَا فَإِذَا أَدْرَكْتُمُوهُمْ فَصَلُّوا فِي بُيُوتِكُمْ فِي الْوَقْتِ الَّذِي تَعْرِفُونَ ثُمَّ صَلُّوا مَعَهُمْ وَاجْعَلُوهَا ‏ ‏سُبْحَةً ‏","","",""],[3420,3420,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةً فَلَا أَدْرِي زَادَ أَمْ نَقَصَ فَلَمَّا سَلَّمَ قِيلَ لَهُ يَا رَسُولَ اللَّهِ هَلْ حَدَثَ فِي الصَّلَاةِ شَيْءٌ قَالَ لَا وَمَا ذَاكَ قَالُوا صَلَّيْتَ كَذَا وَكَذَا قَالَ فَثَنَى رِجْلَيْهِ فَسَجَدَ سَجْدَتَيْ السَّهْوِ فَلَمَّا سَلَّمَ قَالَ ‏ ‏إِنَّمَا أَنَا بَشَرٌ أَنْسَى كَمَا تَنْسَوْنَ وَإِذَا شَكَّ أَحَدُكُمْ فِي الصَّلَاةِ ‏ ‏فَلْيَتَحَرَّ ‏ ‏الصَّلَاةَ فَإِذَا سَلَّمَ فَلْيَسْجُدْ سَجْدَتَيْنِ ‏","","",""],[3421,3421,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ قَوْمِهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏سَمَرَ ‏ ‏بَعْدَ الصَّلَاةِ ‏ ‏يَعْنِي الْعِشَاءَ الْآخِرَةَ ‏ ‏إِلَّا لِأَحَدِ رَجُلَيْنِ مُصَلٍّ أَوْ مُسَافِرٍ ‏","","",""],[3422,3422,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ نَاسٌ يَا رَسُولَ اللَّهِ أَنُؤَاخَذُ بِأَعْمَالِنَا فِي الْجَاهِلِيَّةِ فَقَالَ ‏ ‏مَنْ أَحْسَنَ مِنْكُمْ فِي الْإِسْلَامِ فَلَا يُؤَاخَذُ بِهِ وَمَنْ أَسَاءَ فَيُؤْخَذُ بِعَمَلِهِ الْأَوَّلِ وَالْآخِرِ ‏","","",""],[3423,3423,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏الرُّكَيْنِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكْرَهُ عَشْرَ ‏ ‏خِلَالٍ ‏ ‏تَخَتُّمَ الذَّهَبِ وَجَرَّ ‏ ‏الْإِزَارِ ‏ ‏وَالصُّفْرَةَ ‏ ‏يَعْنِي ‏ ‏الْخَلُوقَ ‏ ‏وَتَغْيِيرَ الشَّيْبِ ‏ ‏قَالَ ‏ ‏جَرِيرٌ ‏ ‏إِنَّمَا ‏ ‏يَعْنِي بِذَلِكَ نَتْفَهُ ‏ ‏وَعَزْلَ ‏ ‏الْمَاءِ ‏ ‏عَنْ ‏ ‏مَحِلِّهِ ‏ ‏وَالرُّقَى إِلَّا ‏ ‏بِالْمُعَوِّذَاتِ ‏ ‏وَفَسَادَ الصَّبِيِّ غَيْرَ مُحَرِّمِهِ وَعَقْدَ ‏ ‏التَّمَائِمِ ‏ ‏وَالتَّبَرُّجَ بِالزِّينَةِ لِغَيْرِ مَحِلِّهَا وَالضَّرْبَ بِالْكِعَابِ ‏","","",""],[3424,3424,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏وَبَعْضُ الْحَدِيثِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَأْ عَلَيَّ قَالَ قُلْتُ أَقْرَأُ عَلَيْكَ وَعَلَيْكَ أُنْزِلَ قَالَ ‏ ‏إِنَّنِي أُحِبُّ أَنْ أَسْمَعَهُ مِنْ غَيْرِي فَقَرَأْتُ حَتَّى إِذَا بَلَغْتُ ‏ { ‏فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّةٍ بِشَهِيدٍ وَجِئْنَا بِكَ عَلَى هَؤُلَاءِ شَهِيدًا ‏} ‏قَالَ رَأَيْتُ عَيْنَيْهِ ‏ ‏تَذْرِفَانِ ‏ ‏دُمُوعًا ‏","","",""],[3425,3425,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقِ بْنِ سَلَمَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏عَبْدِ اللَّهِ ‏ ‏مِنْ ‏ ‏بَنِي بَجِيلَةَ ‏ ‏يُقَالُ لَهُ ‏ ‏نَهِيكُ بْنُ سِنَانٍ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏كَيْفَ تَقْرَأُ هَذِهِ الْآيَةَ أَيَاءً تَجِدُهَا أَوْ أَلِفًا ‏ { ‏مِنْ مَاءٍ غَيْرِ ‏ ‏آسِنٍ ‏ } ‏أَوْ ‏ { ‏غَيْرِ ‏ ‏يَاسِنٍ ‏ } ‏فَقَالَ لَهُ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَوَكُلَّ الْقُرْآنِ أَحْصَيْتَ غَيْرَ هَذِهِ الْآيَةِ قَالَ إِنَّنِي لَأَقْرَأُ ‏ ‏الْمُفَصَّلَ ‏ ‏فِي رَكْعَةٍ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏هَذًّا كَهَذِّ الشِّعْرِ إِنَّ مِنْ أَحْسَنِ الصَّلَاةِ الرُّكُوعَ وَالسُّجُودَ وَلَيَقْرَأَنَّ الْقُرْآنَ أَقْوَامٌ لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ وَلَكِنَّهُ إِذَا قَرَأَهُ ‏ ‏فَرَسَخَ ‏ ‏فِي الْقَلْبِ نَفَعَ إِنِّي لَأَعْرِفُ النَّظَائِرَ الَّتِي كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ سُورَتَيْنِ فِي رَكْعَةٍ قَالَ ثُمَّ قَامَ فَدَخَلَ فَجَاءَ ‏ ‏عَلْقَمَةُ ‏ ‏فَدَخَلَ عَلَيْهِ قَالَ فَقُلْنَا لَهُ سَلْهُ لَنَا عَنْ النَّظَائِرِ الَّتِي كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ سُورَتَيْنِ فِي رَكْعَةٍ قَالَ فَدَخَلَ فَسَأَلَهُ ثُمَّ خَرَجَ إِلَيْنَا فَقَالَ ‏ ‏عِشْرُونَ سُورَةً مِنْ أَوَّلِ ‏ ‏الْمُفَصَّلِ ‏ ‏فِي تَأْلِيفِ ‏ ‏عَبْدِ اللَّهِ ‏","","",""],[3426,3426,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ قَسْمًا قَالَ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏إِنَّ هَذِهِ لَقِسْمَةٌ مَا أُرِيدَ بِهَا وَجْهُ اللَّهِ عَزَّ وَجَلَّ قَالَ فَقُلْتُ يَا عَدُوَّ اللَّهِ أَمَا لَأُخْبِرَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَا قُلْتَ قَالَ فَذَكَرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاحْمَرَّ وَجْهُهُ قَالَ ثُمَّ قَالَ ‏ ‏رَحْمَةُ اللَّهِ عَلَى ‏ ‏مُوسَى ‏ ‏لَقَدْ أُوذِيَ بِأَكْثَرَ مِنْ هَذَا فَصَبَرَ ‏","","",""],[3427,3427,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُبَاشِرْ الْمَرْأَةُ الْمَرْأَةَ حَتَّى تَصِفَهَا لِزَوْجِهَا كَأَنَّمَا يَنْظُرُ إِلَيْهَا ‏","","",""],[3428,3428,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا نَمْشِي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرَّ ‏ ‏بِابْنِ صَيَّادٍ ‏ ‏فَقَالَ إِنِّي قَدْ ‏ ‏خَبَأْتُ ‏ ‏لَكَ ‏ ‏خَبْئًا ‏ ‏قَالَ ‏ ‏ابْنُ صَيَّادٍ ‏ ‏دُخٌّ ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اخْسَأْ ‏ ‏فَلَنْ تَعْدُوَ ‏ ‏قَدْرَكَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ دَعْنِي أَضْرِبْ عُنُقَهُ قَالَ ‏ ‏لَا إِنْ يَكُنْ الَّذِي نَخَافُ فَلَنْ تَسْتَطِيعَ قَتْلَهُ ‏","","",""],[3429,3429,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَكَأَنِّي أَنْظُرُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْكِي ‏ ‏نَبِيًّا ضَرَبَهُ قَوْمُهُ فَهُوَ يَمْسَحُ عَنْ وَجْهِهِ الدَّمَ وَيَقُولُ رَبِّ اغْفِرْ لِقَوْمِي فَإِنَّهُمْ لَا يَعْلَمُونَ ‏","","",""],[3430,3430,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الذَّنْبِ أَكْبَرُ قَالَ ‏ ‏أَنْ تَجْعَلَ لِلَّهِ ‏ ‏نِدًّا ‏ ‏وَهُوَ خَلَقَكَ قَالَ ثُمَّ أَيٌّ قَالَ أَنْ تَقْتُلَ وَلَدَكَ أَنْ ‏ ‏يَطْعَمَ ‏ ‏مَعَكَ قَالَ ثُمَّ أَيٌّ قَالَ أَنْ تُزَانِيَ ‏ ‏حَلِيلَةَ ‏ ‏جَارِكَ قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَأَنْزَلَ اللَّهُ تَصْدِيقَ ذَلِكَ ‏ { ‏وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ ‏ ‏أَثَامًا ‏ }","","",""],[3431,3431,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏عَبْدِ اللَّهِ ‏ ‏فَقَالَ إِنِّي تَرَكْتُ فِي الْمَسْجِدِ رَجُلًا يُفَسِّرُ الْقُرْآنَ بِرَأْيِهِ يَقُولُ فِي هَذِهِ الْآيَةِ ‏ { ‏يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ ‏} ‏إِلَى آخِرِهَا ‏ ‏يَغْشَاهُمْ يَوْمَ الْقِيَامَةِ دُخَانٌ يَأْخُذُ بِأَنْفَاسِهِمْ حَتَّى يُصِيبَهُمْ مِنْهُ كَهَيْئَةِ الزُّكَامِ قَالَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏مَنْ عَلِمَ عِلْمًا فَلْيَقُلْ بِهِ وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلْ اللَّهُ أَعْلَمُ فَإِنَّ مِنْ فِقْهِ الرَّجُلِ أَنْ يَقُولَ لِمَا لَا يَعْلَمُ اللَّهُ أَعْلَمُ إِنَّمَا كَانَ هَذَا لِأَنَّ ‏ ‏قُرَيْشًا ‏ ‏لَمَّا اسْتَعْصَتْ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا عَلَيْهِمْ بِسِنِينَ ‏ ‏كَسِنِي ‏ ‏يُوسُفَ ‏ ‏فَأَصَابَهُمْ ‏ ‏قَحْطٌ ‏ ‏وَجَهِدُوا حَتَّى أَكَلُوا الْعِظَامَ وَجَعَلَ الرَّجُلُ يَنْظُرُ إِلَى السَّمَاءِ فَيَنْظُرُ مَا بَيْنَهُ وَبَيْنَ السَّمَاءِ كَهَيْئَةِ الدُّخَانِ مِنْ ‏ ‏الْجَهْدِ ‏ ‏فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ ‏ ‏يَغْشَى ‏ ‏النَّاسَ هَذَا عَذَابٌ أَلِيمٌ ‏} ‏فَأَتَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ يَا رَسُولَ اللَّهِ اسْتَسْقِ اللَّهَ ‏ ‏لِمُضَرَ ‏ ‏فَإِنَّهُمْ قَدْ هَلَكُوا قَالَ فَدَعَا لَهُمْ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنَّا كَاشِفُو الْعَذَابِ ‏} ‏فَلَمَّا أَصَابَهُمْ الْمَرَّةَ الثَّانِيَةَ عَادُوا فَنَزَلَتْ ‏ { ‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ ‏} ‏يَوْمَ ‏ ‏بَدْرٍ ‏","","",""],[3432,3432,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مُسْتَتِرًا بِسِتَارِ ‏ ‏الْكَعْبَةِ ‏ ‏فَجَاءَ ثَلَاثَةُ نَفَرٍ ‏ ‏قُرَشِيٌّ ‏ ‏وَخَتَنَاهُ ‏ ‏ثَقَفِيَّانِ ‏ ‏أَوْ ‏ ‏ثَقَفِيٌّ ‏ ‏وَخَتَنَاهُ ‏ ‏قُرَشِيَّانِ ‏ ‏كَثِيرٌ شَحْمُ بُطُونِهِمْ قَلِيلٌ فِقْهُ قُلُوبِهِمْ فَتَكَلَّمُوا بِكَلَامٍ لَمْ أَسْمَعْهُ فَقَالَ أَحَدُهُمْ أَتَرَوْنَ اللَّهَ يَسْمَعُ كَلَامَنَا هَذَا فَقَالَ الْآخَرُ ‏ ‏أُرَانَا إِذَا رَفَعْنَا أَصْوَاتَنَا سَمِعَهُ وَإِذَا لَمْ نَرْفَعْهَا لَمْ يَسْمَعْ فَقَالَ الْآخَرُ إِنْ سَمِعَ مِنْهُ شَيْئًا سَمِعَهُ كُلَّهُ قَالَ فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَمَا كُنْتُمْ تَسْتَتِرُونَ أَنْ يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَا أَبْصَارُكُمْ وَلَا جُلُودُكُمْ ‏ ‏إِلَى قَوْلِهِ ‏ ‏ذَلِكُمْ ظَنُّكُمْ الَّذِي ظَنَنْتُمْ بِرَبِّكُمْ أَرْدَاكُمْ فَأَصْبَحْتُمْ مِنْ الْخَاسِرِينَ ‏}","","",""],[3433,3433,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْجَزَّارِ ‏ ‏عَنْ ‏ ‏ابْنِ أَخِي زَيْنَبَ ‏ ‏عَنْ ‏ ‏زَيْنَبَ امْرَأَةِ عَبْدِ اللَّهِ ‏ ‏قَالَتْ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِذَا جَاءَ مِنْ حَاجَةٍ فَانْتَهَى إِلَى الْبَابِ تَنَحْنَحَ وَبَزَقَ كَرَاهِيَةَ أَنْ يَهْجُمَ مِنَّا عَلَى شَيْءٍ يَكْرَهُهُ قَالَتْ وَإِنَّهُ جَاءَ ذَاتَ يَوْمٍ فَتَنَحْنَحَ قَالَتْ وَعِنْدِي عَجُوزٌ ‏ ‏تَرْقِينِي ‏ ‏مِنْ ‏ ‏الْحُمْرَةِ ‏ ‏فَأَدْخَلْتُهَا تَحْتَ السَّرِيرِ فَدَخَلَ فَجَلَسَ إِلَى جَنْبِي فَرَأَى فِي عُنُقِي خَيْطًا قَالَ مَا هَذَا الْخَيْطُ قَالَتْ قُلْتُ خَيْطٌ ‏ ‏أُرْقِيَ ‏ ‏لِي فِيهِ قَالَتْ فَأَخَذَهُ فَقَطَعَهُ ثُمَّ قَالَ إِنَّ آلَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏لَأَغْنِيَاءُ عَنْ الشِّرْكِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏الرُّقَى ‏ ‏وَالتَّمَائِمَ ‏ ‏وَالتِّوَلَةَ ‏ ‏شِرْكٌ قَالَتْ فَقُلْتُ لَهُ لِمَ تَقُولُ هَذَا وَقَدْ كَانَتْ عَيْنِي ‏ ‏تَقْذِفُ ‏ ‏فَكُنْتُ ‏ ‏أَخْتَلِفُ ‏ ‏إِلَى فُلَانٍ الْيَهُودِيِّ ‏ ‏يَرْقِيهَا ‏ ‏وَكَانَ إِذَا ‏ ‏رَقَاهَا ‏ ‏سَكَنَتْ قَالَ إِنَّمَا ذَلِكَ عَمَلُ الشَّيْطَانِ كَانَ ‏ ‏يَنْخُسُهَا ‏ ‏بِيَدِهِ فَإِذَا ‏ ‏رَقَيْتِهَا ‏ ‏كَفَّ عَنْهَا إِنَّمَا كَانَ يَكْفِيكِ أَنْ تَقُولِي كَمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَذْهِبْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ اشْفِ أَنْتَ الشَّافِي لَا شِفَاءَ إِلَّا شِفَاؤُكَ شِفَاءً لَا يُغَادِرُ ‏ ‏سَقَمًا ‏","","",""],[3434,3434,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَحَدَ أَغْيَرُ مِنْ اللَّهِ عَزَّ وَجَلَّ فَلِذَلِكَ حَرَّمَ ‏ ‏الْفَوَاحِشَ ‏ ‏مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَلَا أَحَدَ أَحَبُّ إِلَيْهِ الْمَدْحُ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3435,3435,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَأَنْ أَحْلِفَ بِاللَّهِ تِسْعًا إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُتِلَ قَتْلًا أَحَبُّ إِلَيَّ مِنْ أَنْ أَحْلِفَ وَاحِدَةً وَذَلِك بِأَنَّ اللَّهَ عَزَّ وَجَلَّ اتَّخَذَهُ نَبِيًّا وَجَعَلَهُ شَهِيدًا ‏","","",""],[3436,3436,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏الْحَارِثِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُوعَكُ ‏ ‏فَمَسِسْتُهُ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ ‏ ‏لَتُوعَكُ ‏ ‏وَعْكًا ‏ ‏شَدِيدًا قَالَ أَجَلْ إِنِّي ‏ ‏أُوعَكُ ‏ ‏كَمَا ‏ ‏يُوعَكُ ‏ ‏رَجُلَانِ مِنْكُمْ قُلْتُ إِنَّ لَكَ أَجْرَيْنِ قَالَ نَعَمْ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏مَا عَلَى الْأَرْضِ مُسْلِمٌ يُصِيبُهُ ‏ ‏أَذًى ‏ ‏مِنْ مَرَضٍ فَمَا سِوَاهُ إِلَّا حَطَّ اللَّهُ عَنْهُ بِهِ خَطَايَاهُ كَمَا تَحُطُّ الشَّجَرُ وَرَقَهَا ‏ ‏حَدَّثَنَاه ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏مِثْلَهُ ‏","","",""],[3437,3437,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏تَعَاهَدُوا ‏ ‏هَذِهِ ‏ ‏الْمَصَاحِفَ ‏ ‏وَرُبَّمَا قَالَ الْقُرْآنَ ‏ ‏فَلَهُوَ أَشَدُّ ‏ ‏تَفَصِّيًا ‏ ‏مِنْ صُدُورِ الرِّجَالِ مِنْ النَّعَمِ مِنْ عُقُلِهِ قَالَ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُلْ أَحَدُكُمْ إِنِّي نَسِيتُ آيَةَ كَيْتَ وَكَيْتَ بَلْ هُوَ نُسِّيَ ‏","","",""],[3438,3438,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ إِلَّا بِإِحْدَى ثَلَاثٍ ‏ ‏الثَّيِّبُ ‏ ‏الزَّانِي وَالنَّفْسُ بِالنَّفْسِ وَالتَّارِكُ لِدِينِهِ الْمُفَارِقُ لِلْجَمَاعَةِ ‏","","",""],[3439,3439,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا إِذَا جَلَسْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الصَّلَاةِ قُلْنَا السَّلَامُ عَلَى اللَّهِ قَبْلَ عِبَادِهِ السَّلَامُ عَلَى ‏ ‏جِبْرِيلَ ‏ ‏السَّلَامُ عَلَى ‏ ‏مِيكَائِيلَ ‏ ‏السَّلَامُ عَلَى فُلَانٍ السَّلَامُ عَلَى فُلَانٍ فَسَمِعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ هُوَ السَّلَامُ فَإِذَا جَلَسَ أَحَدُكُمْ فِي الصَّلَاةِ فَلْيَقُلْ التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ فَإِذَا قَالَهَا أَصَابَتْ كُلَّ عَبْدٍ صَالِحٍ فِي السَّمَاءِ وَالْأَرْضِ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ثُمَّ يَتَخَيَّرُ بَعْدُ مِنْ الدُّعَاءِ مَا شَاءَ ‏","","",""],[3440,3440,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُسْلِمٍ الْهَجَرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَنْ سَرَّهُ أَنْ يَلْقَى اللَّهَ عَزَّ وَجَلَّ غَدًا مُسْلِمًا فَلْيُحَافِظْ عَلَى هَؤُلَاءِ الصَّلَوَاتِ ‏ ‏الْمَكْتُوبَاتِ ‏ ‏حَيْثُ ‏ ‏يُنَادَى بِهِنَّ فَإِنَّهُنَّ مِنْ سُنَنِ الْهُدَى وَإِنَّ اللَّهَ عَزَّ وَجَلَّ شَرَعَ لِنَبِيِّكُمْ سُنَنَ الْهُدَى وَمَا مِنْكُمْ إِلَّا وَلَهُ مَسْجِدٌ فِي بَيْتِهِ وَلَوْ صَلَّيْتُمْ فِي بُيُوتِكُمْ كَمَا ‏ ‏يُصَلِّي هَذَا الْمُتَخَلِّفُ فِي بَيْتِهِ لَتَرَكْتُمْ سُنَّةَ نَبِيِّكُمْ وَلَوْ تَرَكْتُمْ سُنَّةَ نَبِيِّكُمْ لَضَلَلْتُمْ وَلَقَدْ رَأَيْتُنِي وَمَا يَتَخَلَّفُ عَنْهَا إِلَّا مُنَافِقٌ مَعْلُومٌ نِفَاقُهُ وَلَقَدْ رَأَيْتُ الرَّجُلَ ‏ ‏يُهَادَى ‏ ‏بَيْنَ الرَّجُلَيْنِ حَتَّى يُقَامَ فِي الصَّفِّ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ رَجُلٍ يَتَوَضَّأُ فَيُحْسِنُ الْوُضُوءَ ثُمَّ يَأْتِي مَسْجِدًا مِنْ الْمَسَاجِدِ ‏ ‏فَيَخْطُو خُطْوَةً إِلَّا رُفِعَ بِهَا دَرَجَةً أَوْ حُطَّ عَنْهُ بِهَا خَطِيئَةٌ أَوْ كُتِبَتْ لَهُ بِهَا حَسَنَةٌ ‏ ‏حَتَّى إِنْ كُنَّا لَنُقَارِبُ بَيْنَ الْخُطَى ‏ ‏وَإِنَّ فَضْلَ صَلَاةِ الرَّجُلِ فِي جَمَاعَةٍ عَلَى صَلَاتِهِ وَحْدَهُ بِخَمْسٍ وَعِشْرِينَ دَرَجَةً ‏","","",""],[3441,3441,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ الصَّادِقُ الْمُصَدَّقُ ‏ ‏إِنَّ أَحَدَكُمْ يُجْمَعُ خَلْقُهُ فِي بَطْنِ أُمِّهِ فِي أَرْبَعِينَ يَوْمًا ثُمَّ يَكُونُ عَلَقَةً مِثْلَ ذَلِكَ ثُمَّ يَكُونُ ‏ ‏مُضْغَةً ‏ ‏مِثْلَ ذَلِكَ ثُمَّ يُرْسَلُ إِلَيْهِ الْمَلَكُ فَيَنْفُخُ فِيهِ الرُّوحَ وَيُؤْمَرُ بِأَرْبَعِ كَلِمَاتٍ رِزْقِهِ وَأَجَلِهِ وَعَمَلِهِ وَشَقِيٌّ أَمْ سَعِيدٌ فَوَالَّذِي لَا إِلَهَ غَيْرُهُ إِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيُخْتَمُ لَهُ بِعَمَلِ أَهْلِ النَّارِ فَيَدْخُلُهَا وَإِنَّ الرَّجُلَ لَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيُخْتَمُ لَهُ بِعَمَلِ أَهْلِ الْجَنَّةِ فَيَدْخُلُهَا ‏","","",""],[3442,3442,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَلِمَةً وَقُلْتُ أُخْرَى قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ ‏ ‏قَالَ ‏ ‏وَقُلْتُ ‏ ‏أَنَا ‏ ‏مَنْ مَاتَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ النَّارَ ‏","","",""],[3443,3443,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏الْحَارِثِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّكُمْ مَالُ وَارِثِهِ أَحَبُّ إِلَيْهِ مِنْ مَالِهِ قَالَ قَالُوا يَا رَسُولَ اللَّهِ مَا مِنَّا أَحَدٌ إِلَّا مَالُهُ أَحَبُّ إِلَيْهِ مِنْ مَالِ وَارِثِهِ قَالَ ‏ ‏اعْلَمُوا أَنَّهُ لَيْسَ مِنْكُمْ أَحَدٌ إِلَّا مَالُ وَارِثِهِ أَحَبُّ إِلَيْهِ مِنْ مَالِهِ مَا لَكَ مِنْ مَالِكَ إِلَّا مَا قَدَّمْتَ وَمَالُ وَارِثِكِ مَا أَخَّرْتَ ‏","","",""],[3444,3444,"","","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَعُدُّونَ فِيكُمْ ‏ ‏الصُّرَعَةَ ‏ ‏قَالَ قُلْنَا الَّذِي لَا يَصْرَعُهُ الرِّجَالُ قَالَ قَالَ لَا وَلَكِنْ ‏ ‏الصُّرَعَةُ ‏ ‏الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ ‏","","",""],[3445,3445,"","","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَعُدُّونَ فِيكُمْ ‏ ‏الرَّقُوبَ ‏ ‏قَالَ قُلْنَا الَّذِي لَا وَلَدَ لَهُ ‏ ‏قَالَ لَا وَلَكِنْ ‏ ‏الرَّقُوبُ ‏ ‏الَّذِي لَمْ يُقَدِّمْ مِنْ وَلَدِهِ شَيْئًا ‏","","",""],[3446,3446,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏الْحَارِثِ بْنِ سُوَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدِيثَيْنِ أَحَدَهُمَا عَنْ نَفْسِهِ وَالْآخَرَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِنَّ الْمُؤْمِنَ يَرَى ذُنُوبَهُ كَأَنَّهُ فِي أَصْلِ جَبَلٍ يَخَافُ أَنْ يَقَعَ عَلَيْهِ وَإِنَّ الْفَاجِرَ يَرَى ذُنُوبَهُ كَذُبَابٍ وَقَعَ عَلَى أَنْفِهِ فَقَالَ لَهُ هَكَذَا فَطَارَ ‏","","",""],[3447,3447,"","","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَلَّهُ أَفْرَحُ بِتَوْبَةِ أَحَدِكُمْ مِنْ رَجُلٍ خَرَجَ بِأَرْضٍ ‏ ‏دَوِّيَّةٍ ‏ ‏مَهْلَكَةٍ مَعَهُ ‏ ‏رَاحِلَتُهُ ‏ ‏عَلَيْهَا طَعَامُهُ وَشَرَابُهُ وَزَادُهُ وَمَا يُصْلِحُهُ فَأَضَلَّهَا فَخَرَجَ فِي طَلَبِهَا حَتَّى إِذَا أَدْرَكَهُ الْمَوْتُ فَلَمْ يَجِدْهَا قَالَ أَرْجِعُ إِلَى مَكَانِي الَّذِي أَضْلَلْتُهَا فِيهِ فَأَمُوتُ فِيهِ قَالَ فَأَتَى مَكَانَهُ فَغَلَبَتْهُ عَيْنُهُ فَاسْتَيْقَظَ فَإِذَا ‏ ‏رَاحِلَتُهُ ‏ ‏عِنْدَ رَأْسِهِ عَلَيْهَا طَعَامُهُ وَشَرَابُهُ وَزَادُهُ وَمَا يُصْلِحُهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏مِثْلَهُ ‏","","",""],[3448,3448,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏الْحَارِثِ بْنِ سُوَيْدٍ ‏ ‏وَالْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَا قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِنَّ الْمُؤْمِنَ يَرَى ذُنُوبَهُ كَأَنَّهُ فِي أَصْلِ جَبَلٍ يَخَافُ أَنْ يَقَعَ عَلَيْهِ وَإِنَّ الْفَاجِرَ يَرَى ذُنُوبَهُ كَذُبَابٍ وَقَعَ عَلَى أَنْفِهِ فَقَالَ بِهِ هَكَذَا فَطَارَ ‏","","",""],[3449,3449,"","","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَلَّهُ أَفْرَحُ بِتَوْبَةِ أَحَدِكُمْ مِنْ رَجُلٍ خَرَجَ بِأَرْضٍ ‏ ‏دَوِّيَّةٍ ‏ ‏ثُمَّ ‏ ‏قَالَ ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدِيثَيْنِ أَحَدَهُمَا عَنْ نَفْسِهِ وَالْآخَرَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَهْلَكَةٍ مَعَهُ ‏ ‏رَاحِلَتُهُ ‏ ‏عَلَيْهَا ‏ ‏زَادُهُ ‏ ‏وَطَعَامُهُ وَشَرَابُهُ وَمَا يُصْلِحُهُ فَأَضَلَّهَا فَخَرَجَ فِي طَلَبِهَا حَتَّى إِذَا أَدْرَكَهُ الْمَوْتُ قَالَ أَرْجِعُ إِلَى مَكَانِي الَّذِي أَضْلَلْتُهَا فِيهِ فَأَمُوتُ فِيهِ قَالَ فَرَجَعَ فَغَلَبَتْهُ عَيْنُهُ فَاسْتَيْقَظَ فَإِذَا ‏ ‏رَاحِلَتُهُ ‏ ‏عِنْدَ رَأْسِهِ عَلَيْهَا ‏ ‏زَادُهُ ‏ ‏وَطَعَامُهُ وَشَرَابُهُ وَمَا يُصْلِحُهُ ‏","","",""],[3450,3450,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُقْتَلُ نَفْسٌ ظُلْمًا إِلَّا كَانَ عَلَى ابْنِ ‏ ‏آدَمَ ‏ ‏الْأَوَّلِ ‏ ‏كِفْلٌ ‏ ‏مِنْ دَمِهَا لِأَنَّهُ كَانَ أَوَّلَ مَنْ ‏ ‏سَنَّ ‏ ‏الْقَتْلَ ‏","","",""],[3451,3451,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏وَيَحْيَى ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏حَدَّثَنِي ‏ ‏عُمَارَةُ ‏ ‏حَدَّثَنِي ‏ ‏الْأَسْوَدُ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏لَا يَجْعَلُ أَحَدُكُمْ لِلشَّيْطَانِ مِنْ نَفْسِهِ جُزْءًا لَا يَرَى إِلَّا أَنَّ حَقًا عَلَيْهِ أَنْ لَا يَنْصَرِفَ إِلَّا عَنْ يَمِينِهِ لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّ أَكْثَرَ انْصِرَافِهِ لَعَلَى يَسَارِهِ ‏","","",""],[3452,3452,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏بَدْرٍ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَقُولُونَ فِي هَؤُلَاءِ الْأَسْرَى قَالَ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا رَسُولَ اللَّهِ قَوْمُكَ وَأَهْلُكَ اسْتَبْقِهِمْ ‏ ‏وَاسْتَأْنِ ‏ ‏بِهِمْ لَعَلَّ اللَّهَ أَنْ يَتُوبَ عَلَيْهِمْ قَالَ وَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ أَخْرَجُوكَ وَكَذَّبُوكَ قَرِّبْهُمْ فَاضْرِبْ أَعْنَاقَهُمْ قَالَ وَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏يَا رَسُولَ اللَّهِ انْظُرْ وَادِيًا كَثِيرَ الْحَطَبِ فَأَدْخِلْهُمْ فِيهِ ثُمَّ ‏ ‏أَضْرِمْ ‏ ‏عَلَيْهِمْ نَارًا قَالَ فَقَالَ ‏ ‏الْعَبَّاسُ ‏ ‏قَطَعْتَ رَحِمَكَ قَالَ فَدَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يَرُدَّ عَلَيْهِمْ شَيْئًا قَالَ فَقَالَ نَاسٌ يَأْخُذُ بِقَوْلِ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَقَالَ نَاسٌ يَأْخُذُ بِقَوْلِ ‏ ‏عُمَرَ ‏ ‏وَقَالَ نَاسٌ يَأْخُذُ بِقَوْلِ ‏ ‏عَبْدِ اللَّهِ بْنِ رَوَاحَةَ ‏ ‏قَالَ فَخَرَجَ عَلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ لَيُلِينُ قُلُوبَ رِجَالٍ فِيهِ حَتَّى تَكُونَ أَلْيَنَ مِنْ اللَّبَنِ وَإِنَّ اللَّهَ لَيَشُدُّ قُلُوبَ رِجَالٍ فِيهِ حَتَّى تَكُونَ أَشَدَّ مِنْ الْحِجَارَةِ وَإِنَّ مَثَلَكَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏كَمَثَلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ ‏ { ‏مَنْ تَبِعَنِي فَإِنَّهُ مِنِّي وَمَنْ عَصَانِي فَإِنَّكَ غَفُورٌ رَحِيمٌ ‏} ‏وَمَثَلَكَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏كَمَثَلِ ‏ ‏عِيسَى ‏ ‏قَالَ ‏ { ‏إِنْ تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِنْ تَغْفِرْ لَهُمْ فَإِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ ‏} ‏وَإِنَّ مَثَلَكَ يَا ‏ ‏عُمَرُ ‏ ‏كَمَثَلِ ‏ ‏نُوحٍ ‏ ‏قَالَ ‏ { ‏رَبِّ لَا تَذَرْ عَلَى الْأَرْضِ مِنْ الْكَافِرِينَ دَيَّارًا ‏} ‏وَإِنَّ مِثْلَكَ يَا ‏ ‏عُمَرُ ‏ ‏كَمَثَلِ ‏ ‏مُوسَى ‏ ‏قَالَ رَبِّ ‏ { ‏اشْدُدْ عَلَى قُلُوبِهِمْ فَلَا يُؤْمِنُوا حَتَّى يَرَوْا الْعَذَابَ الْأَلِيمَ ‏} ‏أَنْتُمْ ‏ ‏عَالَةٌ ‏ ‏فَلَا ‏ ‏يَنْفَلِتَنَّ ‏ ‏مِنْهُمْ أَحَدٌ إِلَّا بِفِدَاءٍ أَوْ ضَرْبَةِ عُنُقٍ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَقُلْتُ ‏ ‏يَا رَسُولَ اللَّهِ إِلَّا ‏ ‏سُهَيْلُ ابْنُ بَيْضَاءَ ‏ ‏فَإِنِّي قَدْ سَمِعْتُهُ يَذْكُرُ الْإِسْلَامَ قَالَ فَسَكَتَ قَالَ فَمَا رَأَيْتُنِي فِي يَوْمٍ أَخْوَفَ أَنْ تَقَعَ عَلَيَّ حِجَارَةٌ مِنْ السَّمَاءِ فِي ذَلِكَ الْيَوْمِ حَتَّى قَالَ إِلَّا ‏ ‏سُهَيْلُ ابْنُ بَيْضَاءَ ‏ ‏قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏مَا كَانَ لِنَبِيٍّ أَنْ يَكُونَ لَهُ أَسْرَى حَتَّى ‏ ‏يُثْخِنَ ‏ ‏فِي الْأَرْضِ تُرِيدُونَ ‏ ‏عَرَضَ ‏ ‏الدُّنْيَا وَاللَّهُ يُرِيدُ الْآخِرَةَ وَاللَّهُ عَزِيزٌ حَكِيمٌ ‏ ‏إِلَى قَوْلِهِ ‏ ‏لَوْلَا كِتَابٌ مِنْ اللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَا أَخَذْتُمْ عَذَابٌ عَظِيمٌ ‏} ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي ابْنَ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏فَذَكَرَ نَحْوَهُ إِلَّا أَنَّهُ قَالَ إِلَّا ‏ ‏سُهَيْلُ ابْنُ بَيْضَاءَ ‏ ‏وَقَالَ فِي قَوْلِ ‏ ‏أَبِي بَكْرٍ ‏ ‏قَالَ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏عِتْرَتُكَ ‏ ‏وَأَصْلُكَ وَقَوْمُكَ ‏ ‏تَجَاوَزْ ‏ ‏عَنْهُمْ يَسْتَنْقِذْهُمْ اللَّهُ بِكَ مِنْ النَّارِ قَالَ وَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏يَا رَسُولَ اللَّهِ أَنْتَ بِوَادٍ كَثِيرِ الْحَطَبِ ‏ ‏فَأَضْرِمْهُ ‏ ‏نَارًا ثُمَّ أَلْقِهِمْ فِيهِ فَقَالَ ‏ ‏الْعَبَّاسُ ‏ ‏قَطَعَ اللَّهُ رَحِمَكَ ‏ ‏حَدَّثَنَاه ‏ ‏حُسَيْنٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ يَعْنِي ابْنَ حَازِمٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏فَذَكَرَ نَحْوَهُ إِلَّا أَنَّهُ قَالَ فَقَامَ ‏ ‏عَبْدُ اللَّهِ بْنُ جَحْشٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَعْدَاءُ اللَّهِ كَذَّبُوكَ وَآذَوْكَ وَأَخْرَجُوكَ وَقَاتَلُوكَ وَأَنْتَ بِوَادٍ كَثِيرِ الْحَطَبِ فَاجْمَعْ لَهُمْ حَطَبًا كَثِيرًا ثُمَّ ‏ ‏أَضْرِمْهُ ‏ ‏عَلَيْهِمْ وَقَالَ ‏ ‏سَهْلُ ابْنُ بَيْضَاءَ ‏","","",""],[3453,3453,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏خِشْفِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ ‏ ‏الدِّيَةَ ‏ ‏فِي الْخَطَإِ أَخْمَاسًا ‏","","",""],[3454,3454,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُسْلِمٍ الْهَجَرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الْمِسْكِينُ بِالطَّوَّافِ وَلَا بِالَّذِي تَرُدُّهُ التَّمْرَةُ وَلَا التَّمْرَتَانِ وَلَا اللُّقْمَةُ وَلَا اللُّقْمَتَانِ وَلَكِنْ الْمِسْكِينُ ‏ ‏الْمُتَعَفِّفُ ‏ ‏الَّذِي لَا يَسْأَلُ النَّاسَ شَيْئًا وَلَا يُفْطَنُ لَهُ فَيُتَصَدَّقَ عَلَيْهِ ‏","","",""],[3455,3455,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى صَلَاةً إِلَّا لِمِيقَاتِهَا إِلَّا صَلَاتَيْنِ صَلَاةَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏بِجَمْعٍ ‏ ‏وَصَلَاةَ الْفَجْرِ يَوْمَئِذٍ قَبْلَ مِيقَاتِهَا ‏","","",""],[3456,3456,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكُمْ بِالصِّدْقِ فَإِنَّ الصِّدْقَ يَهْدِي إِلَى ‏ ‏الْبِرِّ ‏ ‏وَإِنَّ ‏ ‏الْبِرَّ ‏ ‏يَهْدِي إِلَى الْجَنَّةِ وَمَا يَزَالُ الرَّجُلُ يَصْدُقُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ عَزَّ وَجَلَّ صِدِّيقًا وَإِيَّاكُمْ وَالْكَذِبَ فَإِنَّ الْكَذِبَ يَهْدِي إِلَى ‏ ‏الْفُجُورِ ‏ ‏وَإِنَّ ‏ ‏الْفُجُورَ ‏ ‏يَهْدِي إِلَى النَّارِ وَمَا يَزَالُ الرَّجُلُ يَكْذِبُ ‏ ‏وَيَتَحَرَّى ‏ ‏الْكَذِبَ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ عَزَّ وَجَلَّ كَذَّابًا ‏","","",""],[3457,3457,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى الْحَوْضِ وَلَأُنَازَعَنَّ أَقْوَامًا ثُمَّ لَأُغْلَبَنَّ عَلَيْهِمْ فَأَقُولُ يَا رَبِّ أَصْحَابِي فَيَقُولُ إِنَّكَ لَا تَدْرِي مَا ‏ ‏أَحْدَثُوا ‏ ‏بَعْدَكَ ‏","","",""],[3458,3458,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ سَيَكُونُ عَلَيْكُمْ أُمَرَاءُ وَتَرَوْنَ ‏ ‏أَثَرَةً ‏ ‏قَالَ قَالُوا يَا رَسُولَ اللَّهِ فَمَا يَصْنَعُ مَنْ أَدْرَكَ ذَاكَ مِنَّا قَالَ ‏ ‏أَدُّوا الْحَقَّ الَّذِي عَلَيْكُمْ وَسَلُوا اللَّهَ الَّذِي لَكُمْ ‏","","",""],[3459,3459,"","","‏ ‏سَمِعْت ‏ ‏يَحْيَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ وَهْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ سَتَرَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏وَأُمُورًا تُنْكِرُونَهَا قَالَ قُلْنَا مَا تَأْمُرُنَا قَالَ أَدُّوا إِلَيْهِمْ حَقَّهُمْ وَسَلُوا اللَّهَ حَقَّكُمْ ‏","","",""],[3460,3460,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏حَارِثَةَ بْنِ مُضَرِّبٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لِابْنِ النَّوَّاحَةِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْلَا أَنَّكَ رَسُولٌ لَقَتَلْتُكَ فَأَمَّا الْيَوْمَ فَلَسْتَ بِرَسُولٍ يَا ‏ ‏خَرَشَةُ ‏ ‏قُمْ فَاضْرِبْ عُنُقَهُ قَالَ فَقَامَ إِلَيْهِ فَضَرَبَ عُنُقَهُ ‏","","",""],[3461,3461,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏يُسَيْرِ بْنِ جَابِرٍ ‏ ‏قَالَ ‏ ‏هَاجَتْ رِيحٌ حَمْرَاءُ ‏ ‏بِالْكُوفَةِ ‏ ‏فَجَاءَ رَجُلٌ لَيْسَ لَهُ ‏ ‏هِجِّيرَى ‏ ‏إِلَّا يَا ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏جَاءَتْ السَّاعَةُ قَالَ ‏ ‏وَكَانَ مُتَّكِئًا فَجَلَسَ فَقَالَ إِنَّ السَّاعَةَ لَا تَقُومُ حَتَّى لَا يُقْسَمَ مِيرَاثٌ وَلَا يُفْرَحَ بِغَنِيمَةٍ قَالَ عَدُوًّا يَجْمَعُونَ لِأَهْلِ الْإِسْلَامِ وَيَجْمَعُ لَهُمْ أَهْلُ الْإِسْلَامِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ جَاءَهُمْ ‏ ‏الصَّرِيخُ ‏ ‏أَنَّ ‏ ‏الدَّجَّالَ ‏ ‏قَدْ خَلَفَ فِي ‏ ‏ذَرَارِيِّهِمْ ‏ ‏فَيَرْفُضُونَ مَا فِي أَيْدِيهِمْ وَيُقْبِلُونَ فَيَبْعَثُونَ عَشَرَةَ فَوَارِسَ ‏ ‏طَلِيعَةً ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَعْرِفُ أَسْمَاءَهُمْ وَأَسْمَاءَ آبَائِهِمْ وَأَلْوَانَ خُيُولِهِمْ هُمْ خَيْرُ فَوَارِسَ عَلَى ظَهَرِ الْأَرْضِ يَوْمَئِذٍ ‏ ‏أَوْ قَالَ هُمْ مِنْ خَيْرِ فَوَارِسَ عَلَى ظَهَرِ الْأَرْضِ يَوْمَئِذٍ ‏","","",""],[3462,3462,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏كُنْتُ لَا أُحْجَبُ عَنْ ‏ ‏النَّجْوَى ‏ ‏وَلَا عَنْ كَذَا وَلَا عَنْ كَذَا ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏فَنَسِيَ وَاحِدَةً وَنَسِيتُ أَنَا وَاحِدَةً قَالَ فَأَتَيْتُهُ وَعِنْدَهُ ‏ ‏مَالِكُ بْنُ مُرَارَةَ الرَّهَاوِيُّ ‏ ‏فَأَدْرَكْتُ مِنْ آخِرِ حَدِيثِهِ وَهُوَ يَقُولُ ‏ ‏يَا رَسُولَ اللَّهِ قَدْ قُسِمَ لِي مِنْ الْجِمَالِ مَا ‏ ‏تَرَى فَمَا أُحِبُّ أَنَّ أَحَدًا مِنْ النَّاسِ فَضَلَنِي ‏ ‏بِشِرَاكَيْنِ ‏ ‏فَمَا فَوْقَهَا أَفَلَيْسَ ذَلِكَ هُوَ ‏ ‏الْبَغْيُ ‏ ‏قَالَ ‏ ‏لَا لَيْسَ ذَلِكَ ‏ ‏بِالْبَغْيِ ‏ ‏وَلَكِنَّ ‏ ‏الْبَغْيَ ‏ ‏مَنْ ‏ ‏بَطِرَ ‏ ‏قَالَ ‏ ‏أَوْ قَالَ ‏ ‏سَفِهَ ‏ ‏الْحَقَّ ‏ ‏وَغَمَطَ ‏ ‏النَّاسَ ‏","","",""],[3463,3463,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَوْنٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِذَا حُدِّثْتُمْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثًا فَظُنُّوا بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْيَاهُ ‏ ‏وَأَهْدَاهُ وَأَتْقَاهُ ‏","","",""],[3464,3464,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَلَمْ يَزَلْ قَائِمًا حَتَّى هَمَمْتُ بِأَمْرٍ سُوءٍ قُلْنَا وَمَا هَمَمْتَ بِهِ قَالَ هَمَمْتُ أَنْ أَجْلِسَ وَأَدَعَهُ ‏","","",""],[3465,3465,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏زُبَيْدٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سِبَابُ الْمُسْلِمِ فُسُوقٌ وَقِتَالُهُ كُفْرٌ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي وَائِلٍ ‏ ‏أَنْتَ سَمِعْتَ مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ نَعَمْ ‏","","",""],[3466,3466,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا وَقَدْ وُكِّلَ بِهِ قَرِينُهُ مِنْ الْجِنِّ وَقَرِينُهُ مِنْ الْمَلَائِكَةِ قَالُوا وَإِيَّاكَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏وَإِيَّايَ وَلَكِنَّ اللَّهَ أَعَانَنِي عَلَيْهِ فَلَا يَأْمُرُنِي إِلَّا بِحَقٍّ ‏","","",""],[3467,3467,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏مُجَاهِدًا ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا فِي ‏ ‏مَسْجِدِ الْخَيْفِ ‏ ‏لَيْلَةَ ‏ ‏عَرَفَةَ ‏ ‏قَبْلَ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏إِذْ سَمِعْنَا ‏ ‏حِسَّ ‏ ‏الْحَيَّةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْتُلُوا قَالَ فَقُمْنَا قَالَ فَدَخَلَتْ شَقَّ جُحْرٍ فَأُتِيَ بِسَعَفَةٍ ‏ ‏فَأُضْرِمَ ‏ ‏فِيهَا نَارًا وَأَخَذْنَا عُودًا فَقَلَعْنَا عَنْهَا بَعْضَ الْجُحْرِ فَلَمْ نَجِدْهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعُوهَا وَقَاهَا اللَّهُ شَرَّكُمْ كَمَا وَقَاكُمْ شَرَّهَا ‏","","",""],[3468,3468,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ هُوَ ابْنُ أَبِي خَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏قَيْسٌ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نَغْزُو مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ لَنَا نِسَاءٌ فَقُلْنَا يَا رَسُولَ اللَّهِ أَلَا ‏ ‏نَسْتَخْصِي فَنَهَانَا عَنْ ذَلِكَ ‏","","",""],[3469,3469,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنِي ‏ ‏قَيْسٌ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا حَسَدَ إِلَّا فِي اثْنَيْنِ رَجُلٌ آتَاهُ اللَّهُ مَالًا فَسَلَّطَهُ عَلَى هَلَكَتِهِ فِي الْحَقِّ وَرَجُلٌ آتَاهُ اللَّهُ حِكْمَةً فَهُوَ يَقْضِي بِهَا وَيُعَلِّمُهَا النَّاسَ ‏","","",""],[3470,3470,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي يَعْلَى ‏ ‏عَنْ ‏ ‏رَبِيْعِ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ خَطَّ خَطًّا مُرَبَّعًا وَخَطَّ خَطًّا وَسَطَ الْخَطِّ الْمُرَبَّعِ وَخُطُوطًا إِلَى جَنْبِ الْخَطِّ الَّذِي وَسَطَ الْخَطِّ الْمُرَبَّعِ وَخَطٌّ خَارِجٌ مِنْ الْخَطِّ الْمُرَبَّعِ قَالَ هَلْ تَدْرُونَ مَا هَذَا قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏هَذَا الْإِنْسَانُ الْخَطُّ الْأَوْسَطُ وَهَذِهِ الْخُطُوطُ الَّتِي إِلَى جَنْبِهِ الْأَعْرَاضُ تَنْهَشُهُ مِنْ كُلِّ مَكَانٍ إِنْ أَخْطَأَهُ هَذَا أَصَابَهُ هَذَا وَالْخَطُّ الْمُرَبَّعُ الْأَجَلُ الْمُحِيطُ بِهِ وَالْخَطُّ الْخَارِجُ الْأَمَلُ ‏","","",""],[3471,3471,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏أَصَابَ مِنْ امْرَأَةٍ قُبْلَةً فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْأَلُهُ عَنْ كَفَّارَتِهَا فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏أَقِمْ الصَّلَاةَ طَرَفَيْ النَّهَارِ ‏ ‏وَزُلَفًا ‏ ‏مِنْ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ ‏} ‏فَقَالَ يَا رَسُولَ اللَّهِ أَلِي هَذِهِ فَقَالَ لِمَنْ عَمِلَ كَذَا مِنْ أُمَّتِي ‏","","",""],[3472,3472,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمْنَعَنَّ أَحَدَكُمْ أَذَانُ ‏ ‏بِلَالٍ ‏ ‏عَنْ سَحُورِهِ فَإِنَّهُ يُؤَذِّنُ ‏ ‏أَوْ قَالَ يُنَادِي ‏ ‏لِيَرْجِعَ قَائِمُكُمْ وَيَنْتَبِهَ نَائِمُكُمْ لَيْسَ أَنْ يَقُولَ هَكَذَا وَضَمَّ يَدَهُ وَرَفَعَهَا وَلَكِنْ حَتَّى يَقُولَ هَكَذَا وَفَرَّقَ ‏ ‏يَحْيَى ‏ ‏بَيْنَ ‏ ‏السَّبَّابَتَيْنِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏هَذَا الْحَدِيثُ لَمْ أَسْمَعْهُ مِنْ أَحَدٍ ‏","","",""],[3473,3473,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ بْنُ عَتِيقٍ ‏ ‏عَنْ ‏ ‏طَلْقِ بْنِ حَبِيبٍ ‏ ‏عَنِ ‏ ‏الْأَحْنَفِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا هَلَكَ ‏ ‏الْمُتَنَطِّعُونَ ‏ ‏ثَلَاثَ مِرَارٍ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فِي حَدِيثٍ طَوِيلٍ ‏","","",""],[3474,3474,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي الرَّكْعَتَيْنِ كَأَنَّهُ عَلَى ‏ ‏الرَّضْفِ ‏ ‏قُلْتُ حَتَّى يَقُومَ قَالَ حَتَّى يَقُومَ ‏","","",""],[3475,3475,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَامِعُ بْنُ شَدَّادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَلْقَمَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏أَقْبَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏لَيْلًا فَنَزَلْنَا ‏ ‏دَهَاسًا ‏ ‏مِنْ الْأَرْضِ فَقَالَ مَنْ ‏ ‏يَكْلَؤُنَا ‏ ‏فَقَالَ ‏ ‏بِلَالٌ ‏ ‏أَنَا قَالَ إِذًا تَنَامَ قَالَ لَا فَنَامَ حَتَّى طَلَعَتْ الشَّمْسُ فَاسْتَيْقَظَ فُلَانٌ وَفُلَانٌ فِيهِمْ ‏ ‏عُمَرُ ‏ ‏فَقَالَ ‏ ‏اهْضِبُوا ‏ ‏فَاسْتَيْقَظَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏افْعَلُوا مَا كُنْتُمْ تَفْعَلُونَ فَلَمَّا فَعَلُوا قَالَ هَكَذَا فَافْعَلُوا لِمَنْ نَامَ مِنْكُمْ أَوْ نَسِيَ ‏","","",""],[3476,3476,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏زُبَيْدٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ مِنَّا مَنْ ضَرَبَ الْخُدُودَ وَشَقَّ ‏ ‏الْجُيُوبَ ‏ ‏وَدَعَا ‏ ‏بِدَعْوَى ‏ ‏الْجَاهِلِيَّةِ ‏","","",""],[3477,3477,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَمَةَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أُوتِيَ نَبِيُّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَفَاتِيحَ كُلِّ شَيْءٍ غَيْرَ خَمْسٍ ‏ { ‏إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ ‏ ‏الْغَيْثَ ‏ ‏وَيَعْلَمُ مَا فِي الْأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ ‏}","","",""],[3478,3478,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏زُهَيْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏وَعَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَنَا ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكَبِّرُ فِي كُلِّ ‏ ‏خَفْضٍ ‏ ‏وَرَفْعٍ وَقِيَامٍ وَقُعُودٍ وَيُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ حَتَّى يُرَى بَيَاضُ خَدَّيْهِ ‏ ‏أَوْ خَدِّهِ ‏ ‏وَرَأَيْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏يَفْعَلَانِ ذَلِكَ ‏","","",""],[3479,3479,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏قُبَّةٍ ‏ ‏نَحْوٌ مِنْ أَرْبَعِينَ فَقَالَ أَتَرْضَوْنَ أَنْ تَكُونُوا رُبُعَ أَهْلِ الْجَنَّةِ قُلْنَا نَعَمْ قَالَ أَتَرْضَوْنَ أَنْ تَكُونُوا ثُلُثَ أَهْلِ الْجَنَّةِ قُلْنَا نَعَمْ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏إِنِّي لَأَرْجُو أَنْ تَكُونُوا نِصْفَ أَهْلِ الْجَنَّةِ وَذَاكَ أَنَّ الْجَنَّةَ لَا يَدْخُلُهَا إِلَّا نَفْسٌ مُسْلِمَةٌ وَمَا أَنْتُمْ فِي الشِّرْكِ إِلَّا كَالشَّعْرَةِ الْبَيْضَاءِ فِي جِلْدِ ثَوْرٍ أَسْوَدَ أَوْ السَّوْدَاءِ فِي جِلْدِ ثَوْرٍ أَحْمَرَ ‏","","",""],[3480,3480,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أُصَلِّي فَقَالَ ‏ ‏سَلْ ‏ ‏تُعْطَهْ يَا ‏ ‏ابْنَ أُمِّ عَبْدٍ ‏ ‏فَابْتَدَرَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏مَا بَادَرَنِي ‏ ‏أَبُو بَكْرٍ ‏ ‏إِلَى شَيْءٍ إِلَّا سَبَقَنِي إِلَيْهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَسَأَلَاهُ عَنْ قَوْلِهِ فَقَالَ مِنْ دُعَائِي الَّذِي لَا أَكَادُ أَدَعُ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ نَعِيمًا لَا ‏ ‏يَبِيدُ ‏ ‏وَقُرَّةَ عَيْنٍ لَا ‏ ‏تَنْفَدُ ‏ ‏وَمُرَافَقَةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُحَمَّدٍ ‏ ‏فِي أَعْلَى الْجَنَّةِ جَنَّةِ الْخُلْدِ ‏","","",""],[3481,3481,"","","‏ ‏سَمِعْت ‏ ‏يَحْيَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ وَهْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ سَتَرَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏وَأُمُورًا تُنْكِرُونَهَا قَالَ قُلْنَا وَمَا تَأْمُرُنَا قَالَ ‏ ‏أَدُّوا إِلَيْهِمْ حَقَّهُمْ وَسَلُوا اللَّهَ حَقَّكُمْ ‏","","",""],[3482,3482,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ فِي الْمَسْجِدِ فَجِئْنَا نَمْشِي مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏فَلَمَّا رَكَعَ النَّاسُ رَكَعَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَرَكَعْنَا مَعَهُ وَنَحْنُ نَمْشِي فَمَرَّ رَجُلٌ بَيْنَ يَدَيْهِ فَقَالَ السَّلَامُ عَلَيْكَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَهُوَ رَاكِعٌ صَدَقَ اللَّهُ وَرَسُولُهُ فَلَمَّا انْصَرَفَ سَأَلَهُ بَعْضُ الْقَوْمِ لِمَ قُلْتَ حِينَ سَلَّمَ عَلَيْكَ الرَّجُلُ صَدَقَ اللَّهُ وَرَسُولُهُ قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْ أَشْرَاطِ السَّاعَةِ إِذَا كَانَتْ التَّحِيَّةُ عَلَى الْمَعْرِفَةِ ‏","","",""],[3483,3483,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏عَنِ ‏ ‏الزُّبَيْرِ بْنِ عَدِيٍّ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏أُسْرِيَ ‏ ‏بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْتُهِيَ بِهِ إِلَى سِدْرَةِ الْمُنْتَهَى وَهِيَ فِي السَّمَاءِ السَّادِسَةِ إِلَيْهَا يُنْتَهَ مَا ‏ ‏يُعْرَجُ ‏ ‏بِهِ مِنْ الْأَرْضِ فَيُقْبَضُ مِنْهَا وَإِلَيْهَا يُنْتَهَ مَا يُهْبَطُ بِهِ مِنْ فَوْقِهَا فَيُقْبَضُ مِنْهَا قَالَ ‏ { ‏إِذْ ‏ ‏يَغْشَى ‏ ‏السِّدْرَةَ مَا ‏ ‏يَغْشَى ‏ } ‏قَالَ فِرَاشٌ مِنْ ذَهَبٍ قَالَ ‏ ‏فَأُعْطِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثًا وَأُعْطِيَ الصَّلَوَاتِ الْخَمْسَ وَأُعْطِيَ خَوَاتِيمَ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏وَغُفِرَ لِمَنْ لَا يُشْرِكُ بِاللَّهِ مِنْ أُمَّتِهِ شَيْئًا ‏ ‏الْمُقْحِمَاتُ ‏","","",""],[3484,3484,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِلَّهِ مَلَائِكَةً فِي الْأَرْضِ ‏ ‏سَيَّاحِينَ ‏ ‏يُبَلِّغُونِي مِنْ أُمَّتِي السَّلَامَ ‏","","",""],[3485,3485,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجَنَّةُ أَقْرَبُ إِلَى أَحَدِكُمْ مِنْ ‏ ‏شِرَاكِ ‏ ‏نَعْلِهِ وَالنَّارُ مِثْلُ ذَلِكَ ‏","","",""],[3486,3486,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُبَاشِرْ الْمَرْأَةُ الْمَرْأَةَ ‏ ‏لِتَنْعَتَهَا ‏ ‏لِزَوْجِهَا كَأَنَّهُ يَنْظُرُ إِلَيْهَا ‏","","",""],[3487,3487,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَابِعُوا بَيْنَ الْحَجِّ وَالْعُمْرَةِ فَإِنَّهُمَا يَنْفِيَانِ الْفَقْرَ وَالذُّنُوبَ كَمَا يَنْفِي ‏ ‏الْكِيرُ ‏ ‏خَبَثَ ‏ ‏الْحَدِيدِ وَالذَّهَبِ وَالْفِضَّةِ وَلَيْسَ لِلْحَجَّةِ الْمَبْرُورَةِ ‏ ‏ثَوَابٌ ‏ ‏دُونَ الْجَنَّةِ ‏","","",""],[3488,3488,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الْحَفَرِيُّ عُمَرُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ تَغَيَّرَ وَجْهُهُ ثُمَّ قَالَ ‏ ‏نَحْوًا مِنْ ذَا ‏ ‏أَوْ قَرِيبًا مِنْ ذَا ‏","","",""],[3489,3489,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الصَّبَّاحِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُرَّةَ الْهَمْدَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ اسْتَحْيُوا مِنْ اللَّهِ عَزَّ وَجَلَّ حَقَّ الْحَيَاءِ قَالَ قُلْنَا يَا رَسُولَ اللَّهِ إِنَّا نَسْتَحِي وَالْحَمْدُ لِلَّهِ قَالَ لَيْسَ ذَلِكَ وَلَكِنْ ‏ ‏مَنْ اسْتَحَى مِنْ اللَّهِ حَقَّ الْحَيَاءِ فَلْيَحْفَظْ الرَّأْسَ وَمَا ‏ ‏حَوَى ‏ ‏وَلْيَحْفَظْ الْبَطْنَ وَمَا ‏ ‏وَعَى ‏ ‏وَلْيَذْكُرْ الْمَوْتَ ‏ ‏وَالْبِلَى ‏ ‏وَمَنْ أَرَادَ الْآخِرَةَ تَرَكَ زِينَةَ الدُّنْيَا فَمَنْ فَعَلَ ذَلِكَ فَقَدْ اسْتَحْيَا مِنْ اللَّهِ عَزَّ وَجَلَّ حَقَّ الْحَيَاءِ ‏","","",""],[3490,3490,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الصَّبَّاحِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُرَّةَ الْهَمْدَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ قَسَمَ بَيْنَكُمْ أَخْلَاقَكُمْ كَمَا قَسَمَ بَيْنَكُمْ أَرْزَاقَكُمْ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ يُعْطِي الدُّنْيَا مَنْ يُحِبُّ وَمَنْ لَا يُحِبُّ وَلَا يُعْطِي الدِّينَ إِلَّا لِمَنْ أَحَبَّ فَمَنْ أَعْطَاهُ اللَّهُ الدِّينَ فَقَدْ أَحَبَّهُ وَالَّذِي نَفْسِي بِيَدِهِ لَا يُسْلِمُ عَبْدٌ حَتَّى يَسْلَمَ قَلْبُهُ وَلِسَانُهُ وَلَا يُؤْمِنُ حَتَّى يَأْمَنَ جَارُهُ ‏ ‏بَوَائِقَهُ ‏ ‏قَالُوا وَمَا ‏ ‏بَوَائِقُهُ ‏ ‏يَا نَبِيَّ اللَّهِ قَالَ ‏ ‏غَشْمُهُ ‏ ‏وَظُلْمُهُ وَلَا يَكْسِبُ عَبْدٌ مَالًا مِنْ حَرَامٍ فَيُنْفِقَ مِنْهُ فَيُبَارَكَ لَهُ فِيهِ وَلَا يَتَصَدَّقُ بِهِ فَيُقْبَلَ مِنْهُ وَلَا يَتْرُكُ خَلْفَ ظَهْرِهِ إِلَّا كَانَ ‏ ‏زَادَهُ ‏ ‏إِلَى النَّارِ إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَمْحُو السَّيِّئَ بِالسَّيِّئِ وَلَكِنْ يَمْحُو السَّيِّئَ بِالْحَسَنِ إِنَّ ‏ ‏الْخَبِيثَ ‏ ‏لَا يَمْحُو ‏ ‏الْخَبِيث ‏","","",""],[3491,3491,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ الْهَمْدَانِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ ثُلُثُ اللَّيْلِ الْبَاقِي يَهْبِطُ اللَّهُ عَزَّ وَجَلَّ إِلَى السَّمَاءِ الدُّنْيَا ثُمَّ تُفْتَحُ أَبْوَابُ السَّمَاءِ ثُمَّ يَبْسُطُ يَدَهُ فَيَقُولُ هَلْ مِنْ سَائِلٍ يُعْطَى سُؤْلَهُ فَلَا يَزَالُ كَذَلِكَ حَتَّى يَطْلُعَ الْفَجْرُ ‏","","",""],[3492,3492,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَّلُ مَا ‏ ‏يُقْضَى بَيْنَ النَّاسِ يَوْمَ الْقِيَامَةِ فِي الدِّمَاءِ ‏","","",""],[3493,3493,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَأَلَ وَلَهُ مَا يُغْنِيهِ جَاءَتْ يَوْمَ الْقِيَامَةِ خُدُوشًا ‏ ‏أَوْ ‏ ‏كُدُوشًا ‏ ‏فِي وَجْهِهِ قَالُوا يَا رَسُولَ اللَّهِ وَمَا غِنَاهُ قَالَ خَمْسُونَ دِرْهَمًا وَحِسَابُهَا مِنْ الذَّهَبِ ‏","","",""],[3494,3494,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ السَّمَّاكِ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنِ ‏ ‏الْمُسَيَّبِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَشْتَرُوا السَّمَكَ فِي الْمَاءِ فَإِنَّهُ ‏ ‏غَرَرٌ ‏","","",""],[3495,3495,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ مُحَمَّدٍ ‏ ‏ابْنُ أُخْتِ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَبْعَثُ يَوْمَ الْقِيَامَةِ مُنَادِيًا يُنَادِي يَا ‏ ‏آدَمُ ‏ ‏إِنَّ اللَّهَ يَأْمُرُكَ أَنْ تَبْعَثَ بَعْثًا مِنْ ذُرِّيَّتِكَ إِلَى النَّارِ فَيَقُولُ ‏ ‏آدَمُ ‏ ‏يَا رَبِّ وَمِنْ كَمْ قَالَ فَيُقَالُ لَهُ مِنْ كُلِّ مِائَةٍ تِسْعَةً وَتِسْعِينَ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ مَنْ هَذَا النَّاجِي مِنَّا بَعْدَ هَذَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏هَلْ تَدْرُونَ مَا أَنْتُمْ فِي النَّاسِ إِلَّا ‏ ‏كَالشَّامَةِ ‏ ‏فِي صَدْرِ الْبَعِيرِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُسْلِمٍ أَبِي إِسْحَاقَ الْهَجَرِيِّ ‏ ‏فَذَكَرَ مَعْنَاهُ وَقَالَ فَيَقُولُ ‏ ‏آدَمُ ‏ ‏يَا رَبِّ كَمْ أَبْعَثُ ‏","","",""],[3496,3496,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَتَّقِ أَحَدُكُمْ وَجْهَهُ النَّارَ وَلَوْ ‏ ‏بِشِقِّ ‏ ‏تَمْرَةٍ ‏","","",""],[3497,3497,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏الْهَجَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ خَادِمُ أَحَدِكُمْ بِطَعَامِهِ فَلْيَبْدَأْ بِهِ فَلْيُطْعِمْهُ أَوْ لِيُجْلِسْهُ مَعَهُ فَإِنَّهُ ‏ ‏وَلِيَ ‏ ‏حَرَّهُ ‏ ‏وَدُخَانَهُ ‏","","",""],[3498,3498,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏أَلَا أُصَلِّي لَكُمْ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَصَلَّى فَلَمْ يَرْفَعْ يَدَيْهِ إِلَّا مَرَّةً ‏","","",""],[3499,3499,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَجَدَ ‏ ‏بِالنَّجْمِ ‏ ‏وَسَجَدَ الْمُسْلِمُونَ إِلَّا رَجُلًا مِنْ ‏ ‏قُرَيْشٍ ‏ ‏أَخَذَ كَفًّا مِنْ تُرَابٍ فَرَفَعَهُ إِلَى جَبْهَتِهِ فَسَجَدَ عَلَيْهِ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَرَأَيْتُهُ بَعْدُ قُتِلَ كَافِرًا ‏","","",""],[3500,3500,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا أُنْزِلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏ ‏كَانَ يُكْثِرُ إِذَا قَرَأَهَا وَرَكَعَ أَنْ يَقُولَ ‏ ‏سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ ثَلَاثًا ‏","","",""],[3501,3501,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْنُكَ عَلَيَّ أَنْ تَرْفَعَ الْحِجَابَ وَأَنْ تَسْتَمِعَ ‏ ‏سِوَادِي ‏ ‏حَتَّى ‏ ‏أَنْهَاكَ ‏ ‏سِوَادِي سِرِّي قَالَ أَذِنَ لَهُ أَنْ يَسْمَعَ سِرَّهُ ‏","","",""],[3502,3502,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَهَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَاجَتِهِ ‏ ‏فَقَالَ الْتَمِسْ لِي ثَلَاثَةَ أَحْجَارٍ قَالَ فَأَتَيْتُهُ بِحَجَرَيْنِ ‏ ‏وَرَوْثَةٍ ‏ ‏قَالَ ‏ ‏فَأَخَذَ الْحَجَرَيْنِ وَأَلْقَى ‏ ‏الرَّوْثَةَ ‏ ‏وَقَالَ إِنَّهَا ‏ ‏رِكْسٌ ‏","","",""],[3503,3503,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْدِبُ ‏ ‏لَنَا ‏ ‏السَّمَرَ ‏ ‏بَعْدَ الْعِشَاءِ ‏","","",""],[3504,3504,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الطِّيَرَةُ ‏ ‏شِرْكٌ وَمَا مِنَّا إِلَّا وَلَكِنَّ اللَّهَ يُذْهِبُهُ بِالتَّوَكُّلِ ‏","","",""],[3505,3505,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ أَمْشِي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏حَرْثٍ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَهُوَ مُتَّكِئٌ عَلَى ‏ ‏عَسِيبٍ ‏ ‏قَالَ فَمَرَّ بِقَوْمٍ مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ بَعْضُهُمْ لِبَعْضٍ سَلُوهُ عَنْ الرُّوحِ قَالَ بَعْضُهُمْ لَا تَسْأَلُوهُ فَسَأَلُوهُ عَنْ الرُّوحِ فَقَالُوا يَا ‏ ‏مُحَمَّدُ ‏ ‏مَا الرُّوحُ فَقَامَ فَتَوَكَّأَ عَلَى ‏ ‏الْعَسِيبِ ‏ ‏قَالَ فَظَنَنْتُ أَنَّهُ يُوحَى إِلَيْهِ فَقَالَ ‏ { ‏وَيَسْأَلُونَكَ عَنْ الرُّوحِ قُلْ الرُّوحُ مِنْ أَمْرِ رَبِّي وَمَا أُوتِيتُمْ مِنْ الْعِلْمِ إِلَّا قَلِيلًا ‏} ‏قَالَ فَقَالَ بَعْضُهُمْ قَدْ قُلْنَا لَكُمْ لَا تَسْأَلُوهُ ‏","","",""],[3506,3506,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا إِنِّي أَبْرَأُ إِلَى كُلِّ ‏ ‏خَلِيلٍ ‏ ‏مِنْ ‏ ‏خُلَّتِهِ ‏ ‏وَلَوْ اتَّخَذْتُ ‏ ‏خَلِيلًا ‏ ‏لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏خَلِيلًا ‏ ‏إِنَّ صَاحِبَكُمْ ‏ ‏خَلِيلُ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3507,3507,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُؤْتَى بِالسَّبْيِ ‏ ‏فَيُعْطِي أَهْلَ الْبَيْتِ جَمِيعًا كَرَاهِيَةَ أَنْ يُفَرِّقَ بَيْنهُمْ ‏","","",""],[3508,3508,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي قَيْسٍ ‏ ‏عَنِ ‏ ‏الْهُزَيْلِ بْنِ شُرَحْبِيلٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏أَبِي مُوسَى ‏ ‏وَسُلَيْمَانَ بْنِ رَبِيعَةَ ‏ ‏فَسَأَلَهُمَا عَنْ ابْنَةٍ وَابْنَةِ ابْنٍ وَأُخْتٍ لِأَبٍ فَقَالَا لِلْبِنْتِ النِّصْفُ وَلِلْأُخْتِ النِّصْفُ وَأْتِ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏فَإِنَّهُ سَيُتَابِعُنَا قَالَ فَأَتَى ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏فَسَأَلَهُ وَأَخْبَرَهُ بِمَا قَالَا فَقَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏لَقَدْ ضَلَلْتُ إِذًا وَمَا أَنَا مِنْ الْمُهْتَدِينَ ‏ ‏سَأَقْضِي بِمَا ‏ ‏قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلِابْنَةِ النِّصْفُ وَلِابْنَةِ ‏ ‏الِابْنِ السُّدُسُ تَكْمِلَةَ الثُّلُثَيْنِ وَمَا بَقِيَ فَلِلْأُخْتِ ‏","","",""],[3509,3509,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى ‏ ‏وَالْعِفَّةَ ‏ ‏وَالْغِنَى ‏","","",""],[3510,3510,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ مُعَاوِيَةَ الدُّهْنِيِّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ الْأَشْجَعِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ سُمَيَّةَ ‏ ‏مَا عُرِضَ عَلَيْهِ أَمْرَانِ قَطُّ إِلَّا اخْتَارَ الْأَرْشَدَ مِنْهُمَا ‏","","",""],[3511,3511,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏جَمَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ أَرْبَعُونَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَكُنْتُ مِنْ آخِرِ مَنْ أَتَاهُ فَقَالَ ‏ ‏إِنَّكُمْ مُصِيبُونَ وَمَنْصُورُونَ وَمَفْتُوحٌ لَكُمْ فَمَنْ أَدْرَكَ ذَلِكَ مِنْكُمْ فَلْيَتَّقِ اللَّهَ وَلْيَأْمُرْ بِالْمَعْرُوفِ وَلْيَنْهَ عَنْ الْمُنْكَرِ وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[3512,3512,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَأَبِي مُوسَى ‏ ‏فَقَالَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ بَيْنَ يَدَيْ السَّاعَةِ أَيَّامًا يَنْزِلُ فِيهَا الْجَهْلُ وَيُرْفَعُ فِيهَا الْعِلْمُ وَيَكْثُرُ فِيهَا الْهَرْجُ قَالَ قُلْنَا وَمَا الْهَرْجُ قَالَ الْقَتْلُ ‏","","",""],[3513,3513,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏بَشِيرُ بْنُ سَلْمَانَ ‏ ‏عَنْ ‏ ‏سَيَّارٍ أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ نَزَلَ بِهِ حَاجَةٌ فَأَنْزَلَهَا بِالنَّاسِ كَانَ ‏ ‏قَمِنًا ‏ ‏مِنْ أَنْ لَا تَسْهُلَ حَاجَتُهُ وَمَنْ أَنْزَلَهَا بِاللَّهِ آتَاهُ بِرِزْقٍ عَاجِلٍ أَوْ بِمَوْتٍ آجِلٍ ‏","","",""],[3514,3514,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏خُمَيْرِ بْنِ مَالِكٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَرَأْتُ مِنْ ‏ ‏فِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعِينَ سُورَةً ‏ ‏وَزَيْدُ بْنُ ثَابِتٍ ‏ ‏لَهُ ‏ ‏ذُؤَابَةٌ ‏ ‏فِي الْكُتَّابِ ‏","","",""],[3515,3515,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ مُحَمَّدٍ أَبُو سَعِيدٍ يَعْنِي الْعَنْقَزِيَّ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏وَأَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏وَحَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏مُخَارِقٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏شَهِدْتُ مِنْ ‏ ‏الْمِقْدَادِ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏ابْنِ الْأَسْوَدِ ‏ ‏مَشْهَدًا ‏ ‏لَأَنْ أَكُونَ أَنَا صَاحِبَهُ أَحَبُّ إِلَيَّ مِمَّا ‏ ‏عُدِلَ ‏ ‏بِهِ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَدْعُو عَلَى الْمُشْرِكِينَ فَقَالَ وَاللَّهِ يَا رَسُولَ اللَّهِ لَا نَقُولُ كَمَا قَالَتْ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏لِمُوسَى ‏ { ‏اذْهَبْ أَنْتَ وَرَبُّكَ فَقَاتِلَا إِنَّا هَاهُنَا قَاعِدُونَ ‏} ‏وَلَكِنْ نُقَاتِلُ عَنْ يَمِينِكَ وَعَنْ يَسَارِكَ وَمِنْ بَيْنِ يَدَيْكَ وَمِنْ خَلْفِكَ فَرَأَيْتُ وَجْهَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُشْرِقُ وَسَرَّهُ ذَلِكَ ‏ ‏قَالَ ‏ ‏أَسْوَدُ ‏ ‏فَرَأَيْتُ وَجْهَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُشْرِقُ لِذَلِكَ وَسَرَّهُ ذَلِكَ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشْرَقَ وَجْهُهُ وَسَرَّهُ ذَاكَ ‏","","",""],[3516,3516,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ حَتَّى يُرَى بَيَاضُ خَدِّهِ ‏","","",""],[3517,3517,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ عَبْدِ اللَّهِ الْيَشْكُرِيِّ ‏ ‏عَنْ ‏ ‏الْمَعْرُورِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏أُمُّ حَبِيبَةَ ابْنَةُ أَبِي سُفْيَانَ ‏ ‏اللَّهُمَّ أَمْتِعْنِي بِزَوْجِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِأَبِي ‏ ‏أَبِي سُفْيَانَ ‏ ‏وَبِأَخِي ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكِ سَأَلْتِ اللَّهَ لِآجَالٍ ‏ ‏مَضْرُوبَةٍ ‏ ‏وَأَيَّامٍ مَعْدُودَةٍ وَأَرْزَاقٍ مَقْسُومَةٍ لَنْ يُعَجَّلَ شَيْءٌ قَبْلَ ‏ ‏حِلِّهِ ‏ ‏أَوْ يُؤَخَّرَ شَيْءٌ عَنْ ‏ ‏حِلِّهِ ‏ ‏وَلَوْ كُنْتِ سَأَلْتِ اللَّهَ أَنْ يُعِيذَكِ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ كَانَ أَخْيَرَ ‏ ‏أَوْ أَفْضَلَ ‏ ‏قَالَ وَذُكِرَ عِنْدَهُ الْقِرَدَةُ ‏ ‏قَالَ ‏ ‏مِسْعَرٌ ‏ ‏أُرَاهُ قَالَ وَالْخَنَازِيرُ ‏ ‏إِنَّهُ مِمَّا ‏ ‏مُسِخَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَمْ ‏ ‏يَمْسَخْ ‏ ‏شَيْئًا فَيَدَعَ لَهُ نَسْلًا أَوْ ‏ ‏عَاقِبَةً ‏ ‏وَقَدْ كَانَتْ الْقِرَدَةُ ‏ ‏أَوْ الْخَنَازِيرُ ‏ ‏قَبْلَ ذَلِكَ ‏","","",""],[3518,3518,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ قَوْمًا أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا ‏ ‏صَاحِبٌ لَنَا ‏ ‏يَشْتَكِي ‏ ‏أَنَكْوِيهِ قَالَ فَسَكَتَ ثُمَّ قَالُوا ‏ ‏أَنَكْوِيهِ فَسَكَتَ ثُمَّ قَالَ اكْوُوهُ ‏ ‏وَارْضِفُوهُ ‏ ‏رَضْفًا ‏","","",""],[3519,3519,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَا نَسِيتُ فِيمَا نَسِيتُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ حَتَّى يُرَى ‏ ‏أَوْ نَرَى ‏ ‏بَيَاضَ خَدَّيْهِ ‏","","",""],[3520,3520,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْبَغِي لِأَحَدٍ أَنْ يَقُولَ أَنَا خَيْرٌ مِنْ ‏ ‏يُونُسَ بْنِ مَتَّى ‏","","",""],[3521,3521,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْمَسْعُودِيِّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ الثَقَفِيِّ ‏ ‏أَوْ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏شَكَّ ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنِ ‏ ‏عَبْدَةَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَمْ يُحَرِّمْ حُرْمَةً إِلَّا وَقَدْ عَلِمَ أَنَّهُ سَيَطَّلِعُهَا مِنْكُمْ مُطَّلِعٌ أَلَا وَإِنِّي آخِذٌ ‏ ‏بِحُجَزِكُمْ ‏ ‏أَنْ تَهَافَتُوا فِي النَّارِ كَتَهَافُتِ الْفَرَاشِ أَوْ الذُّبَابِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدَةَ النَّهْدِيِّ ‏ ‏فَذَكَرَهُ ‏ ‏وَكَذَا ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏وَأَبَو كَامِلٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏وَقَالَ الْفَرَاشِ أَوْ الذُّبَابِ ‏","","",""],[3522,3522,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نَغْزُو مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ شَبَابٌ وَلَيْسَ لَنَا نِسَاءٌ فَقُلْنَا يَا رَسُولَ اللَّهِ أَلَا ‏ ‏نَسْتَخْصِي ‏ ‏فَنَهَانَا عَنْ ذَلِكَ ‏","","",""],[3523,3523,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏الْعَوَّامُ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو إِسْحَاقَ الشَّيْبَانِيُّ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَدُورُ ‏ ‏رَحَى ‏ ‏الْإِسْلَامِ عَلَى رَأْسِ خَمْسٍ وَثَلَاثِينَ أَوْ سِتٍّ وَثَلَاثِينَ أَوْ سَبْعٍ وَثَلَاثِينَ فَإِنْ هَلَكُوا فَسَبِيلُ مَنْ هَلَكَ وَإِنْ بَقُوا ‏ ‏يَقُمْ ‏ ‏لَهُمْ دِينُهُمْ سَبْعِينَ سَنَةً ‏","","",""],[3524,3524,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَيْثُ قُتِلَ ‏ ‏ابْنُ النَّوَّاحَةِ ‏ ‏إِنَّ هَذَا ‏ ‏وَابْنَ أُثَالٍ ‏ ‏كَانَا أَتَيَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَسُولَيْنِ ‏ ‏لمُسَيْلِمَةَ الْكَذَّابِ ‏ ‏فَقَالَ لَهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَشْهَدَانِ أَنِّي رَسُولُ اللَّهِ قَالَا نَشْهَدُ أَنَّ ‏ ‏مُسَيْلِمَةَ ‏ ‏رَسُولُ اللَّهِ فَقَالَ لَوْ كُنْتُ قَاتِلًا رَسُولًا لَضَرَبْتُ أَعْنَاقَكُمَا قَالَ فَجَرَتْ سُنَّةً أَنْ لَا يُقْتَلَ الرَّسُولُ فَأَمَّا ‏ ‏ابْنُ أُثَالٍ ‏ ‏فَكَفَانَاهُ ‏ ‏اللَّهُ عَزَّ وَجَلَّ وَأَمَّا هَذَا فَلَمْ يَزَلْ ذَلِكَ فِيهِ حَتَّى أَمْكَنَ اللَّهُ مِنْهُ الْآنَ ‏","","",""],[3525,3525,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ النَّخَعِيِّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏اضْطَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى حَصِيرٍ ‏ ‏فَأَثَّرَ ‏ ‏فِي جَنْبِهِ فَلَمَّا اسْتَيْقَظَ جَعَلْتُ أَمْسَحُ جَنْبَهُ فَقُلْتُ يَا رَسُولَ اللَّهِ أَلَا آذَنْتَنَا حَتَّى نَبْسُطَ لَكَ عَلَى الْحَصِيرِ شَيْئًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لِي وَلِلدُّنْيَا مَا أَنَا وَالدُّنْيَا إِنَّمَا مَثَلِي وَمَثَلُ الدُّنْيَا كَرَاكِبٍ ظَلَّ تَحْتَ شَجَرَةٍ ثُمَّ رَاحَ وَتَرَكَهَا ‏","","",""],[3526,3526,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَلْقَمَةَ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏لَمَّا انْصَرَفْنَا مِنْ ‏ ‏غَزْوَةِ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَحْرُسُنَا اللَّيْلَةَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَقُلْتُ أَنَا حَتَّى عَادَ مِرَارًا قُلْتُ أَنَا يَا رَسُولَ اللَّهِ قَالَ فَأَنْتَ إِذًا قَالَ فَحَرَسْتُهُمْ حَتَّى إِذَا كَانَ وَجْهُ الصُّبْحِ أَدْرَكَنِي قَوْلُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكَ تَنَامُ فَنِمْتُ فَمَا أَيْقَظَنَا إِلَّا حَرُّ الشَّمْسِ فِي ظُهُورِنَا فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصَنَعَ كَمَا كَانَ يَصْنَعُ مِنْ الْوُضُوءِ وَرَكْعَتَيْ الْفَجْرِ ثُمَّ صَلَّى بِنَا الصُّبْحَ فَلَمَّا انْصَرَفَ قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَوْ أَرَادَ أَنْ لَا تَنَامُوا لَمْ تَنَامُوا وَلَكِنْ أَرَادَ أَنْ تَكُونُوا لِمَنْ بَعْدَكُمْ فَهَكَذَا لِمَنْ نَامَ أَوْ نَسِيَ قَالَ ثُمَّ إِنَّ نَاقَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِبِلَ الْقَوْمِ تَفَرَّقَتْ فَخَرَجَ النَّاسُ فِي طَلَبِهَا فَجَاءُوا بِإِبِلِهِمْ إِلَّا نَاقَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذْ هَهُنَا فَأَخَذْتُ حَيْثُ قَالَ لِي فَوَجَدْتُ ‏ ‏زِمَامَهَا ‏ ‏قَدْ الْتَوَى عَلَى شَجَرَةٍ مَا كَانَتْ لِتَحُلَّهَا إِلَّا يَدٌ قَالَ فَجِئْتُ بِهَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ وَالَّذِي بَعَثَكَ بِالْحَقِّ نَبِيًّا لَقَدْ وَجَدْتُ ‏ ‏زِمَامَهَا ‏ ‏مُلْتَوِيًا عَلَى شَجَرَةٍ مَا كَانَتْ لِتَحُلَّهَا إِلَّا يَدٌ قَالَ وَنَزَلَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُورَةُ ‏ ‏الْفَتْحِ ‏ { ‏إِنَّا فَتَحْنَا لَكَ فَتْحًا مُبِينًا ‏}","","",""],[3527,3527,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْحَارِثِ الْجَابِرِ ‏ ‏عَنْ ‏ ‏أَبِي مَاجِدٍ ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏بِابْنِ أَخٍ لَهُ فَقَالَ إِنَّ هَذَا ابْنُ أَخِي وَقَدْ شَرِبَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَقَدْ عَلِمْتُ أَوَّلَ ‏ ‏حَدٍّ ‏ ‏كَانَ فِي الْإِسْلَامِ امْرَأَةٌ سَرَقَتْ فَقُطِعَتْ يَدُهَا فَتَغَيَّرَ لِذَلِكَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَغَيُّرًا شَدِيدًا ثُمَّ قَالَ ‏ { ‏وَلْيَعْفُوا وَلْيَصْفَحُوا أَلَا تُحِبُّونَ أَنْ يَغْفِرَ اللَّهُ لَكُمْ وَاللَّهُ غَفُورٌ رَحِيمٌ ‏}","","",""],[3528,3528,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏فُضَيْلُ بْنُ مَرْزُوقٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْجُهَنِيُّ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَصَابَ أَحَدًا قَطُّ هَمٌّ وَلَا حَزَنٌ فَقَالَ ‏ ‏اللَّهُمَّ إِنِّي عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ ‏ ‏نَاصِيَتِي ‏ ‏بِيَدِكَ مَاضٍ فِيَّ حُكْمُكَ عَدْلٌ فِيَّ قَضَاؤُكَ أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ أَوْ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي وَنُورَ صَدْرِي وَجِلَاءَ حُزْنِي وَذَهَابَ هَمِّي إِلَّا أَذْهَبَ اللَّهُ هَمَّهُ وَحُزْنَهُ وَأَبْدَلَهُ مَكَانَهُ فَرَجًا قَالَ فَقِيلَ يَا رَسُولَ اللَّهِ أَلَا نَتَعَلَّمُهَا فَقَالَ بَلَى يَنْبَغِي لِمَنْ سَمِعَهَا أَنْ يَتَعَلَّمَهَا ‏","","",""],[3529,3529,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏شَرِيكُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ بَذِيمَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا وَقَعَتْ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏فِي الْمَعَاصِي نَهَتْهُمْ عُلَمَاؤُهُمْ فَلَمْ يَنْتَهُوا فَجَالَسُوهُمْ فِي مَجَالِسِهِمْ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏أَحْسِبُهُ قَالَ وَأَسْوَاقِهِمْ ‏ ‏وَوَاكَلُوهُمْ وَشَارَبُوهُمْ فَضَرَبَ اللَّهُ قُلُوبَ بَعْضِهِمْ بِبَعْضٍ وَلَعَنَهُمْ عَلَى لِسَانِ ‏ ‏دَاوُدَ ‏ ‏وَعِيسَى ابْنِ مَرْيَمَ ‏ { ‏ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ ‏} ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَّكِئًا فَجَلَسَ فَقَالَ لَا وَالَّذِي نَفْسِي بِيَدِهِ حَتَّى ‏ ‏تَأْطُرُوهُمْ ‏ ‏عَلَى الْحَقِّ ‏ ‏أَطْرًا ‏","","",""],[3530,3530,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ البُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ آخِرَ مَنْ يَدْخُلُ الْجَنَّةَ رَجُلٌ يَمْشِي عَلَى الصِّرَاطِ فَيَنْكَبُّ مَرَّةً وَيَمْشِي مَرَّةً ‏ ‏وَتَسْفَعُهُ ‏ ‏النَّارُ مَرَّةً فَإِذَا جَاوَزَ الصِّرَاطَ الْتَفَتَ إِلَيْهَا فَقَالَ تَبَارَكَ الَّذِي نَجَّانِي مِنْكِ لَقَدْ أَعْطَانِي اللَّهُ مَا لَمْ يُعْطِ أَحَدًا مِنْ الْأَوَّلِينَ وَالْآخِرِينَ قَالَ فَتُرْفَعُ لَهُ شَجَرَةٌ فَيَنْظُرُ إِلَيْهَا فَيَقُولُ يَا رَبِّ ‏ ‏أَدْنِنِي ‏ ‏مِنْ هَذِهِ الشَّجَرَةِ فَأَسْتَظِلَّ بِظِلِّهَا وَأَشْرَبَ مِنْ مَائِهَا فَيَقُولُ أَيْ عَبْدِي فَلَعَلِّي إِنْ ‏ ‏أَدْنَيْتُكَ ‏ ‏مِنْهَا سَأَلْتَنِي غَيْرَهَا فَيَقُولُ لَا يَا رَبِّ وَيُعَاهِدُ اللَّهَ أَنْ لَا يَسْأَلَهُ غَيْرَهَا وَالرَّبُّ عَزَّ وَجَلَّ يَعْلَمُ أَنَّهُ سَيَسْأَلُهُ لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ ‏ ‏يَعْنِي عَلَيْهِ ‏ ‏فَيُدْنِيهِ مِنْهَا ثُمَّ تُرْفَعُ لَهُ شَجَرَةٌ وَهِيَ أَحْسَنُ مِنْهَا فَيَقُولُ يَا رَبِّ ‏ ‏أَدْنِنِي ‏ ‏مِنْ هَذِهِ الشَّجَرَةِ فَأَسْتَظِلَّ بِظِلِّهَا وَأَشْرَبَ مِنْ مَائِهَا فَيَقُولُ أَيْ عَبْدِي أَلَمْ تُعَاهِدْنِي ‏ ‏يَعْنِي أَنَّكَ لَا تَسْأَلُنِي غَيْرَهَا ‏ ‏فَيَقُولُ يَا رَبِّ هَذِهِ لَا أَسْأَلُكَ غَيْرَهَا وَيُعَاهِدُهُ وَالرَّبُّ يَعْلَمُ أَنَّهُ سَيَسْأَلُهُ غَيْرَهَا ‏ ‏فَيُدْنِيهِ ‏ ‏مِنْهَا فَتُرْفَعُ لَهُ شَجَرَةٌ عِنْدَ بَابِ الْجَنَّةِ هِيَ أَحْسَنُ مِنْهَا فَيَقُولُ رَبِّ ‏ ‏أَدْنِنِي ‏ ‏مِنْ هَذِهِ الشَّجَرَةِ أَسْتَظِلُّ بِظِلِّهَا وَأَشْرَبُ مِنْ مَائِهَا فَيَقُولُ أَيْ عَبْدِي أَلَمْ تُعَاهِدْنِي أَنْ لَا تَسْأَلَنِي غَيْرَهَا فَيَقُولُ يَا رَبِّ هَذِهِ الشَّجَرَةُ لَا أَسْأَلُكَ غَيْرَهَا وَيُعَاهِدُهُ وَالرَّبُّ يَعْلَمُ أَنَّهُ سَيَسْأَلُهُ غَيْرَهَا لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْهَا ‏ ‏فَيُدْنِيهِ ‏ ‏مِنْهَا فَيَسْمَعُ أَصْوَاتَ أَهْلِ الْجَنَّةِ فَيَقُولُ يَا رَبِّ الْجَنَّةَ الْجَنَّةَ فَيَقُولُ عَبْدِي أَلَمْ تُعَاهِدْنِي أَنَّكَ لَا تَسْأَلُنِي غَيْرَهَا فَيَقُولُ يَا رَبِّ أَدْخِلْنِي الْجَنَّةَ قَالَ فَيَقُولُ عَزَّ وَجَلَّ ‏ ‏مَا ‏ ‏يَصْرِينِي مِنْكَ أَيْ عَبْدِي ‏ ‏أَيُرْضِيكَ أَنْ أُعْطِيَكَ مِنْ الْجَنَّةِ الدُّنْيَا وَمِثْلَهَا مَعَهَا قَالَ فَيَقُولُ أَتَهْزَأُ بِي وَأَنْتَ رَبُّ الْعِزَّةِ قَالَ فَضَحِكَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏ ‏ثُمَّ قَالَ أَلَا تَسْأَلُونِي لِمَ ضَحِكْتُ قَالُوا لَهُ لِمَ ضَحِكْتَ قَالَ لِضَحِكِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا تَسْأَلُونِي لِمَ ضَحِكْتُ قَالُوا لِمَ ضَحِكْتَ يَا رَسُولَ اللَّهِ قَالَ لِضَحِكِ الرَّبِّ حِينَ قَالَ أَتَهْزَأُ بِي وَأَنْتَ رَبُّ الْعِزَّةِ ‏","","",""],[3531,3531,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنِي ‏ ‏شُعْبَةُ بْنُ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْكَنُودِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ خَاتَمِ الذَّهَبِ أَوْ حَلَقَةِ الذَّهَبِ ‏","","",""],[3532,3532,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَبَسُونَا عَنْ صَلَاةِ الْوُسْطَى حَتَّى غَابَتْ الشَّمْسُ مَلَأَ اللَّهُ بُطُونَهُمْ وَقُبُورَهُمْ نَارًا ‏","","",""],[3533,3533,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَمْنَعَنَّ أَحَدَكُمْ أَذَانُ ‏ ‏بِلَالٍ ‏ ‏مِنْ سَحُورِهِ فَإِنَّهُ إِنَّمَا يُنَادِي ‏ ‏أَوْ قَالَ يُؤَذِّنُ ‏ ‏لِيَرْجِعَ قَائِمُكُمْ وَيُنَبِّهَ نَائِمَكُمْ لَيْسَ أَنْ يَقُولَ هَكَذَا وَلَكِنْ حَتَّى يَقُولَ هَكَذَا وَضَمَّ ‏ ‏ابْنُ أَبِي عَدِيٍّ أَبُو عَمْرٍو ‏ ‏أَصَابِعَهُ وَصَوَّبَهَا وَفَتَحَ مَا بَيْنَ أُصْبُعَيْهِ ‏ ‏السَّبَّابَتَيْنِ ‏ ‏يَعْنِي الْفَجْرَ ‏","","",""],[3534,3534,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ ‏","","",""],[3535,3535,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ مِمَّا يُكْثِرُ أَنْ يَقُولَ سُبْحَانَكَ رَبَّنَا وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي قَالَ فَلَمَّا نَزَلَتْ ‏ ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏ ‏قَالَ ‏ ‏سُبْحَانَكَ رَبَّنَا وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ ‏","","",""],[3536,3536,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ عَلَّمَنَا خُطْبَةَ الْحَاجَةِ ‏ ‏الْحَمْدُ لِلَّهِ نَسْتَعِينُهُ وَنَسْتَغْفِرُهُ وَنَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ وَمَنْ يُضْلِلْ فَلَا هَادِيَ لَهُ وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ثُمَّ يَقْرَأُ ثَلَاثَ آيَاتٍ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ ‏} { ‏يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا ‏ ‏وَبَثَّ ‏ ‏مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً وَاتَّقُوا اللَّهَ الَّذِي ‏ ‏تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا ‏} { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَنْ يُطِعْ اللَّهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزًا عَظِيمًا ‏} ‏ثُمَّ تَذْكُرُ حَاجَتَكَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏وَأَبِي الْأَحْوَصِ ‏ ‏قَالَ ‏ ‏وَهَذَا حَدِيثُ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏عَلَّمَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُطْبَتَيْنِ خُطْبَةَ الْحَاجَةِ وَخُطْبَةَ الصَّلَاةِ الْحَمْدُ لِلَّهِ أَوْ إِنَّ الْحَمْدَ لِلَّهِ نَسْتَعِينُهُ فَذَكَرَ مَعْنَاهُ ‏","","",""],[3537,3537,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاجِدٌ وَحَوْلَهُ نَاسٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏إِذْ جَاءَ ‏ ‏عُقْبَةُ بْنُ أَبِي مُعَيْطٍ ‏ ‏بِسَلَى ‏ ‏جَزُورٍ ‏ ‏فَقَذَفَهُ عَلَى ظَهْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَرْفَعْ رَأْسَهُ فَجَاءَتْ ‏ ‏فَاطِمَةُ ‏ ‏فَأَخَذَتْهُ مِنْ ظَهْرِهِ وَدَعَتْ عَلَى مَنْ صَنَعَ ذَلِكَ قَالَ فَقَالَ ‏ ‏اللَّهُمَّ عَلَيْكَ الْمَلَأَ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏أَبَا جَهْلِ بْنَ هِشَامٍ ‏ ‏وَعُتْبَةَ بْنَ رَبِيعَةَ ‏ ‏وَشَيْبَةَ بْنَ رَبِيعَةَ ‏ ‏وَعُقْبَةَ بْنَ أَبِي مُعَيْطٍ ‏ ‏وَأُمَيَّةَ بْنَ خَلَفٍ ‏ ‏أَوْ ‏ ‏أُبَيَّ بْنَ خَلَفٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏الشَّاكُّ ‏ ‏قَالَ ‏ ‏فَلَقَدْ رَأَيْتُهُمْ قُتِلُوا يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَأُلْقُوا فِي بِئْرٍ غَيْرَ أَنَّ ‏ ‏أُمَيَّةَ ‏ ‏أَوْ ‏ ‏أُبَيًّا ‏ ‏تَقَطَّعَتْ أَوْصَالُهُ فَلَمْ يُلْقَ فِي الْبِئْرِ ‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ ‏ ‏عَمْرَو بْنَ هِشَامٍ ‏ ‏وَأُمَيَّةَ بْنَ خَلَفٍ ‏ ‏وَزَادَ ‏ ‏وَعِمَارَةَ بْنَ الْوَلِيدِ ‏","","",""],[3538,3538,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏عَنِ ‏ ‏النَّزَّالِ بْنِ سَبْرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَمِعْتُ رَجُلًا يَقْرَأُ آيَةً وَسَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيْرَهَا فَأَتَيْتُ بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ عَرَفْتُ فِي وَجْهِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَرَاهِيَةَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كِلَاكُمَا مُحْسِنٌ إِنَّ مَنْ قَبْلَكُمْ اخْتَلَفُوا فِيهِ فَأَهْلَكَهُمْ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَحَدَّثَنِي ‏ ‏مِسْعَرٌ ‏ ‏عَنْهُ وَرَفَعَهُ إِلَى ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا تَخْتَلِفُوا ‏","","",""],[3539,3539,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا تَصْلُحُ سَفْقَتَانِ فِي سَفْقَةٍ وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَعَنَ اللَّهُ آكِلَ الرِّبَا ‏ ‏وَمُوكِلَهُ وَشَاهِدَهُ وَكَاتِبَهُ ‏","","",""],[3540,3540,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَحْسِبُهُ قَدْ رَفَعَهُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الَّذِي يُعِينُ عَشِيرَتَهُ عَلَى غَيْرِ الْحَقِّ مَثَلُ الْبَعِيرِ ‏ ‏رُدِّيَ ‏ ‏فِي بِئْرٍ فَهُوَ ‏ ‏يَمُدُّ ‏ ‏بِذَنَبِهِ ‏","","",""],[3541,3541,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَزَالُ الرَّجُلُ يَصْدُقُ ‏ ‏وَيَتَحَرَّى ‏ ‏الصِّدْقَ حَتَّى يُكْتَبَ صِدِّيقًا وَلَا يَزَالُ يَكْذِبُ ‏ ‏وَيَتَحَرَّى ‏ ‏الْكَذِبَ حَتَّى يُكْتَبَ كَذَّابًا ‏","","",""],[3542,3542,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هُنَيِّ بْنِ نُوَيْرَةَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَعَفُّ النَّاسِ قِتْلَةً أَهْلُ الْإِيمَانِ ‏","","",""],[3543,3543,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَعَفَّ النَّاسِ قِتْلَةً أَهْلُ الْإِيمَانِ ‏","","",""],[3544,3544,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ نَاجِيَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَدُورُ ‏ ‏رَحَى ‏ ‏الْإِسْلَامِ بِخَمْسٍ وَثَلَاثِينَ أَوْ سِتٍّ وَثَلَاثِينَ أَوْ سَبْعٍ وَثَلَاثِينَ فَإِنْ يَهْلَكُوا فَسَبِيلُ مَنْ قَدْ هَلَكَ وَإِنْ ‏ ‏يَقُمْ ‏ ‏لَهُمْ دِينُهُمْ ‏ ‏يَقُمْ ‏ ‏لَهُمْ سَبْعِينَ عَامًا قَالَ قُلْتُ أَمِمَّا مَضَى أَمْ مِمَّا بَقِيَ قَالَ مِمَّا بَقِيَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ نَاجِيَةَ الْكَاهِلِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ إِلَّا أَنَّهُ قَالَ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏مَا مَضَى أَمْ مَا بَقِيَ قَالَ مَا بَقِيَ ‏","","",""],[3545,3545,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ يَعْنِي ابْنَ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏أَذِنْتُ لَكَ أَنْ تَرْفَعَ الْحِجَابَ وَتَسْمَعَ ‏ ‏سِوَادِي ‏ ‏حَتَّى ‏ ‏أَنْهَاكَ ‏","","",""],[3546,3546,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عِيَاضٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَحَبَّ ‏ ‏الْعُرَاقِ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الذِّرَاعُ ذِرَاعُ الشَّاةِ وَكَانَ قَدْ سُمَّ فِي الذِّرَاعِ وَكَانَ يَرَى أَنَّ ‏ ‏الْيَهُودَ ‏ ‏هُمْ سَمُّوهُ ‏","","",""],[3547,3547,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى الْجَابِرُ أَبُو الْحَارِثِ التَّيْمِيُّ ‏ ‏أَنَّ ‏ ‏أَبَا مَاجدٍ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي حَنِيفَةَ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏سَأَلْنَا نَبِيَّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ السَّيْرِ بِالْجِنَازَةِ فَقَالَ ‏ ‏السَّيْرُ مَا دُونَ ‏ ‏الْخَبَبِ ‏ ‏فَإِنْ يَكُ خَيْرًا تُعْجَلْ إِلَيْهِ ‏ ‏أَوْ قَالَ لِتُعْجَلْ إِلَيْهِ ‏ ‏وَإِنْ يَكُ سِوَى ذَاكَ فَبُعْدًا لِأَهْلِ النَّارِ الْجِنَازَةُ مَتْبُوعَةٌ وَلَا تَتْبَعُ لَيْسَ مِنَّا مَنْ تَقَدَّمَهَا ‏","","",""],[3548,3548,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْأَقْمَرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْأَحْوَصِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ إِلَّا عَلَى شِرَارِ النَّاسِ ‏","","",""],[3549,3549,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏وَعَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكَبِّرُ فِي كُلِّ رَفْعٍ وَوَضْعٍ وَقِيَامٍ وَقُعُودٍ وَيُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ حَتَّى أَرَى بَيَاضَ خَدِّهِ وَرَأَيْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏يَفْعَلَانِ ذَاكَ ‏","","",""],[3550,3550,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آكِلَ الرِّبَا ‏ ‏وَمُوكِلَهُ وَشَاهِدَيْهِ وَكَاتِبَهُ ‏","","",""],[3551,3551,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ أَبِي رَاشِدٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُنَا التَّشَهُّدَ كَمَا يُعَلِّمُنَا السُّورَةَ مِنْ الْقُرْآنِ ‏","","",""],[3552,3552,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏ثُوَيْرِ بْنِ أَبِي فَاخِتَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَبَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏","","",""],[3553,3553,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏فِي قَوْلِهِ مَا كَذَبَ الْفُؤَادُ مَا رَأَى قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جِبْرِيلَ ‏ ‏فِي ‏ ‏حُلَّةٍ ‏ ‏مِنْ ‏ ‏رَفْرَفٍ ‏ ‏قَدْ مَلَأَ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ ‏","","",""],[3554,3554,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَقْرَأَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَنَا ‏ { ‏الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ ‏}","","",""],[3555,3555,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا وَضَعَ جَنْبَهُ عَلَى فِرَاشِهِ قَالَ ‏ ‏قِنِي عَذَابَكَ يَوْمَ تَجْمَعُ عِبَادَكَ ‏","","",""],[3556,3556,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ ‏ ‏هَمَمْتُ أَنْ آمُرَ رَجُلًا فَيُصَلِّيَ بِالنَّاسِ ثُمَّ آمُرَ بِأُنَاسٍ لَا يُصَلُّونَ مَعَنَا فَتُحَرَّقَ عَلَيْهِمْ بُيُوتُهُمْ ‏","","",""],[3557,3557,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏وَأَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو أَحْمَدَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ أَنْ يَدْعُوَ ثَلَاثًا وَيَسْتَغْفِرَ ثَلَاثًا ‏","","",""],[3558,3558,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مُنْذُ أُنْزِلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏ ‏كَانَ يُكْثِرُ أَنْ يَقُولَ إِذَا قَرَأَهَا ثُمَّ رَكَعَ بِهَا أَنْ يَقُولَ ‏ ‏سُبْحَانَكَ رَبَّنَا وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ ثَلَاثًا ‏","","",""],[3559,3559,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزيِدَ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي ابْنَ الْفُرَاتِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَعْيَنِ الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ الْجُشَمِيِّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏يَخْطُبُ ذَاتَ يَوْمٍ فَإِذَا هُوَ بِحَيَّةٍ تَمْشِي عَلَى الْجِدَارِ فَقَطَعَ خُطْبَتَهُ ثُمَّ ضَرَبَهَا بِقَضِيبِهِ ‏ ‏أَوْ بِقَصَبَةٍ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏بِقَضِيبِهِ ‏ ‏حَتَّى قَتَلَهَا ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ قَتَلَ حَيَّةً فَكَأَنَّمَا قَتَلَ رَجُلًا مُشْرِكًا قَدْ ‏ ‏حَلَّ ‏ ‏دَمُهُ ‏","","",""],[3560,3560,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَعْيَنِ الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ الْجُشَمِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْقِرَدَةِ وَالْخَنَازِيرِ أَهِيَ مِنْ نَسْلِ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَمْ يَلْعَنْ قَوْمًا قَطُّ ‏ ‏فَمَسَخَهُمْ ‏ ‏فَكَانَ لَهُمْ نَسْلٌ حِينَ يُهْلِكُهُمْ وَلَكِنْ هَذَا خَلْقٌ كَانَ فَلَمَّا غَضِبَ اللَّهُ عَلَى ‏ ‏الْيَهُودِ ‏ ‏مَسَخَهُمْ فَجَعَلَهُمْ مِثْلَهُمْ ‏","","",""],[3561,3561,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جِبْرِيلَ ‏ ‏فِي صُورَتِهِ وَلَهُ سِتُّ مِائَةِ جَنَاحٍ كُلُّ جَنَاحٍ مِنْهَا قَدْ سَدَّ ‏ ‏الْأُفُقَ ‏ ‏يَسْقُطُ مِنْ جَنَاحِهِ مِنْ التَّهَاوِيلِ وَالدُّرِّ وَالْيَاقُوتِ مَا اللَّهُ بِهِ عَلِيمٌ ‏","","",""],[3562,3562,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏فِي قَوْلِهِ ‏ { ‏وَاتَّخَذَ اللَّهُ ‏ ‏إِبْرَاهِيمَ ‏ ‏خَلِيلًا ‏} ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ رِبْعِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ اللَّهَ اتَّخَذَ صَاحِبَكُمْ ‏ ‏خَلِيلًا ‏ ‏يَعْنِي ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[3563,3563,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ رِبْعِيٍّ الْأَسَدِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ صَاحِبَكُمْ ‏ ‏خَلِيلُ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3564,3564,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ رِبْعِيٍّ الْأَسَدِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ صَاحِبَكُمْ ‏ ‏خَلِيلُ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3565,3565,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ رِبْعِيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ صَاحِبَكُمْ ‏ ‏خَلِيلُ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3566,3566,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ رِبْعِيٍّ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِنَّ صَاحِبَكُمْ خَلِيلُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[3567,3567,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ بْنِ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الرِّبَا وَإِنْ كَثُرَ فَإِنَّ عَاقِبَتَهُ تَصِيرُ إِلَى قُلٍّ ‏","","",""],[3568,3568,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَقْرَأَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِنْ ‏ ‏مُدَّكِرٍ ‏ } ‏فَقَالَ رَجُلٌ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏مُدَّكِرٍ ‏ ‏أَوْ مُذَّكِّرٍ قَالَ أَقْرَأَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُدَّكِرٍ ‏","","",""],[3569,3569,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏أَنْبَأَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ بْنِ الرَّبِيعِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخَيْلُ ثَلَاثَةٌ فَفَرَسٌ لِلرَّحْمَنِ وَفَرَسٌ لِلْإِنْسَانِ وَفَرَسٌ لِلشَّيْطَانِ فَأَمَّا فَرَسُ الرَّحْمَنِ فَالَّذِي يُرْبَطُ فِي سَبِيلِ اللَّهِ فَعَلَفُهُ وَرَوْثُهُ وَبَوْلُهُ وَذَكَرَ مَا شَاءَ اللَّهُ وَأَمَّا فَرَسُ الشَّيْطَانِ فَالَّذِي يُقَامَرُ ‏ ‏أَوْ يُرَاهَنُ ‏ ‏عَلَيْهِ وَأَمَّا فَرَسُ الْإِنْسَانِ فَالْفَرَسُ يَرْتَبِطُهَا الْإِنْسَانُ ‏ ‏يَلْتَمِسُ ‏ ‏بَطْنَهَا فَهِيَ تَسْتُرُ مِنْ فَقْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏الرُّكَيْنُ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ الْخَيْلُ ثَلَاثَةٌ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[3570,3570,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ بْنِ نَاجِيَةَ الْكَاهِلِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏رَحَى ‏ ‏الْإِسْلَامِ سَتَزُولُ بِخَمْسٍ وَثَلَاثِينَ أَوْ سِتٍّ وَثَلَاثِينَ أَوْ سَبْعٍ وَثَلَاثِينَ فَإِنْ يَهْلَكْ فَكَسَبِيلِ مَنْ أُهْلِكَ وَإِنْ ‏ ‏يَقُمْ ‏ ‏لَهُمْ دِينُهُمْ ‏ ‏يَقُمْ ‏ ‏لَهُمْ سَبْعِينَ عَامًا قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ أَبِمَا مَضَى أَمْ بِمَا بَقِيَ قَالَ بَلْ بِمَا بَقِيَ ‏","","",""],[3571,3571,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِسْرَائِيلَ بْنَ يُونُسَ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ هِشَامٍ ‏ ‏مَوْلَى ‏ ‏الْهَمْدَانِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَصْحَابِهِ ‏ ‏لَا يُبَلِّغْنِي أَحَدٌ عَنْ أَحَدٍ مِنْ أَصْحَابِي شَيْئًا فَإِنِّي أُحِبُّ أَنْ أَخْرُجَ إِلَيْكُمْ وَأَنَا سَلِيمُ الصَّدْرِ قَالَ وَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَالٌ فَقَسَمَهُ قَالَ فَمَرَرْتُ بِرَجُلَيْنِ وَأَحَدُهُمَا يَقُولُ لِصَاحِبِهِ وَاللَّهِ مَا أَرَادَ ‏ ‏مُحَمَّدٌ ‏ ‏بِقِسْمَتِهِ وَجْهَ اللَّهِ وَلَا الدَّارَ الْآخِرَةَ فَتَثَبَّتُّ حَتَّى سَمِعْتُ مَا قَالَا ثُمَّ أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ قُلْتَ لَنَا لَا يُبَلِّغْنِي أَحَدٌ عَنْ أَحَدٍ مِنْ أَصْحَابِي شَيْئًا وَإِنِّي مَرَرْتُ بِفُلَانٍ وَفُلَانٍ وَهُمَا يَقُولَانِ كَذَا وَكَذَا قَالَ فَاحْمَرَّ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَشَقَّ عَلَيْهِ ثُمَّ قَالَ دَعْنَا مِنْكَ فَقَدْ أُوذِيَ ‏ ‏مُوسَى ‏ ‏أَكْثَرَ مِنْ ذَلِكَ ثُمَّ صَبَرَ ‏","","",""],[3572,3572,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَخَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْعِشَاءِ ثُمَّ خَرَجَ إِلَى الْمَسْجِدِ فَإِذَا النَّاسُ يَنْتَظِرُونَ الصَّلَاةَ قَالَ ‏ ‏أَمَا إِنَّهُ لَيْسَ مِنْ أَهْلِ هَذِهِ الْأَدْيَانِ أَحَدٌ يَذْكُرُ اللَّهَ هَذِهِ السَّاعَةَ غَيْرُكُمْ قَالَ وَأَنْزَلَ هَؤُلَاءِ الْآيَاتِ ‏ { ‏لَيْسُوا سَوَاءً مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏حَتَّى بَلَغَ ‏ ‏وَمَا تَفْعَلُوا مِنْ خَيْرٍ فَلَنْ تُكْفَرُوهُ وَاللَّهُ عَلِيمٌ بِالْمُتَّقِينَ ‏}","","",""],[3573,3573,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏ابْنُ النَّوَّاحَةِ ‏ ‏وَابْنُ أُثَالٍ ‏ ‏رَسُولَا ‏ ‏مُسَيْلِمَةَ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُمَا ‏ ‏أَتَشْهَدَانِ أَنِّي رَسُولُ اللَّهِ قَالَا نَشْهَدُ أَنَّ ‏ ‏مُسَيْلِمَةَ ‏ ‏رَسُولُ اللَّهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آمَنْتُ بِاللَّهِ وَرُسُلِهِ لَوْ كُنْتُ قَاتِلًا رَسُولًا لَقَتَلْتُكُمَا ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ ‏ ‏فَمَضَتْ السُّنَّةُ أَنَّ الرُّسُلَ لَا تُقْتَلُ ‏","","",""],[3574,3574,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا نَرَى الْآيَاتِ فِي زَمَانِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَرَكَاتٍ وَأَنْتُمْ تَرَوْنَهَا تَخْوِيفًا ‏","","",""],[3575,3575,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏نَزَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْزِلًا فَانْطَلَقَ لِحَاجَتِهِ فَجَاءَ وَقَدْ أَوْقَدَ رَجُلٌ عَلَى قَرْيَةِ نَمْلٍ إِمَّا فِي الْأَرْضِ وَإِمَّا فِي شَجَرَةٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّكُمْ فَعَلَ هَذَا فَقَالَ رَجُلٌ مِنْ الْقَوْمِ أَنَا يَا رَسُولَ اللَّهِ قَالَ اطْفُهَا اطْفُهَا ‏","","",""],[3576,3576,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَمْرِو بْنِ جَعْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَجُلًا أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْأَلُهُ عَنْ لَيْلَةِ الْقَدْرِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّكُمْ يَذْكُرُ لَيْلَةَ الصَّهْبَاوَاتِ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَنَا وَاللَّهِ أَذْكُرُهَا يَا رَسُولَ اللَّهِ بِأَبِي أَنْتَ وَأُمِّي وَإِنَّ فِي يَدَيَّ لَتَمَرَاتٍ أَتَسَحَّرُ بِهِنَّ مُسْتَتِرًا ‏ ‏بِمُؤْخِرَةِ رَحْلِي ‏ ‏مِنْ الْفَجْرِ وَذَلِكَ حِينَ طَلَعَ الْقَمَرُ ‏","","",""],[3577,3577,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا قُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏مِنَّا أَمِيرٌ وَمِنْكُمْ أَمِيرٌ قَالَ فَأَتَاهُمْ ‏ ‏عُمَرُ ‏ ‏فَقَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَلَسْتُمْ تَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏أَبَا بَكْرٍ ‏ ‏أَنْ يَؤُمَّ بِالنَّاسِ فَأَيُّكُمْ تَطِيبُ نَفْسُهُ أَنْ يَتَقَدَّمَ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَقَالُوا نَعُوذُ بِاللَّهِ أَنْ نَتَقَدَّمَ ‏ ‏أَبَا بَكْرٍ ‏","","",""],[3578,3578,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَطَالَ الْقِيَامَ حَتَّى هَمَمْتُ بِأَمْرِ سُوءٍ قَالَ قُلْنَا وَمَا هُوَ قَالَ هَمَمْتُ أَنْ أَقْعُدَ ‏","","",""],[3579,3579,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَيُّ الظُّلْمِ أَعْظَمُ قَالَ ‏ ‏ذِرَاعٌ مِنْ الْأَرْضِ يَنْتَقِصُهُ مِنْ حَقِّ أَخِيهِ فَلَيْسَتْ حَصَاةٌ مِنْ الْأَرْضِ أَخَذَهَا إِلَّا طُوِّقَهَا يَوْمَ الْقِيَامَةِ إِلَى قَعْرِ الْأَرْضِ وَلَا يَعْلَمُ قَعْرَهَا إِلَّا الَّذِي خَلَقَهَا ‏","","",""],[3580,3580,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي الْفُرَاتِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَعْيَنِ الْعَبْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ الْجُشَمِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْقِرَدَةِ وَالْخَنَازِيرِ أَمِنْ نَسْلِ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَمْ يَلْعَنْ قَوْمًا قَطُّ ‏ ‏فَمَسَخَهُمْ ‏ ‏وَكَانَ لَهُمْ نَسْلٌ حَتَّى يُهْلِكَهُمْ وَلَكِنَّ اللَّهَ عَزَّ وَجَلَّ غَضِبَ عَلَى ‏ ‏الْيَهُودِ ‏ ‏فَمَسَخَهُمْ ‏ ‏وَجَعَلَهُمْ مِثْلَهُمْ ‏","","",""],[3581,3581,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ أَنْ يَدْعُوَ ثَلَاثًا وَيَسْتَغْفِرَ ثَلَاثًا ‏","","",""],[3582,3582,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ أَنْ يَدْعُوَ ثَلَاثًا وَيَسْتَغْفِرَ ثَلَاثًا ‏","","",""],[3583,3583,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَقْرَأَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَنَا الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ ‏","","",""],[3584,3584,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عُبَيْدِ بْنِ رِفَاعَةَ ‏ ‏أَنَّ ‏ ‏أَبَا مُحَمَّدٍ ‏ ‏أَخْبَرَهُ ‏ ‏وَكَانَ مِنْ أَصْحَابِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏حَدَّثَهُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ذَكَرَ عِنْدَهُ الشُّهَدَاءَ فَقَالَ ‏ ‏إِنَّ أَكْثَرَ شُهَدَاءِ أُمَّتِي أَصْحَابُ الْفُرُشِ وَرُبَّ قَتِيلٍ بَيْنَ الصَّفَّيْنِ اللَّهُ أَعْلَمُ ‏ ‏بِنِيَّتِهِ ‏","","",""],[3585,3585,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَيُّ الظُّلْمِ أَظْلَمُ قَالَ ‏ ‏ذِرَاعٌ مِنْ الْأَرْضِ يَنْتَقِصُهَا الْمَرْءُ الْمُسْلِمُ مِنْ حَقِّ أَخِيهِ فَلَيْسَ حَصَاةٌ مِنْ الْأَرْضِ يَأْخُذُهَا أَحَدٌ إِلَّا طُوِّقَهَا يَوْمَ الْقِيَامَةِ إِلَى قَعْرِ الْأَرْضِ وَلَا يَعْلَمُ قَعْرَهَا إِلَّا اللَّهُ عَزَّ وَجَلَّ الَّذِي خَلَقَهَا ‏","","",""],[3586,3586,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏الرُّكَيْنُ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَكْرَهُ عَشْرَ ‏ ‏خِلَالٍ ‏ ‏الصُّفْرَةُ ‏ ‏وَتَغْيِيرُ الشَّيْبِ وَتَخَتُّمُ الذَّهَبِ وَجَرُّ ‏ ‏الْإِزَارِ ‏ ‏وَالتَّبَرُّجُ بِالزِّينَةِ بِغَيْرِ مَحِلِّهَا وَضَرْبُ الْكِعَابِ ‏ ‏وَعَزْلُ ‏ ‏الْمَاءِ ‏ ‏عَنْ مَحَلِّهِ وَفَسَادُ الصَّبِيِّ غَيْرَ مُحَرِّمِهِ وَعَقْدُ ‏ ‏التَّمَائِمِ ‏ ‏وَالرُّقَى إِلَّا بِالْمُعَوِّذَاتِ ‏","","",""],[3587,3587,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏اسْتَقْبَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيْتَ ‏ ‏فَدَعَا عَلَى ‏ ‏نَفَرٍ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏سَبْعَةٍ فِيهِمْ ‏ ‏أَبُو جَهْلٍ ‏ ‏وَأُمَيَّةُ بْنُ خَلَفٍ ‏ ‏وَعُتْبَةُ بْنُ رَبِيعَةَ ‏ ‏وَشَيْبَةُ ‏ ‏وَعُقْبَةُ بْنُ أَبِي مُعَيْطٍ ‏ ‏فَأُقْسِمُ بِاللَّهِ لَقَدْ رَأَيْتُهُمْ ‏ ‏صَرْعَى ‏ ‏عَلَى ‏ ‏بَدْرٍ ‏ ‏وَقَدْ غَيَّرَتْهُمْ الشَّمْسُ وَكَانَ يَوْمًا حَارًّا ‏","","",""],[3588,3588,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُنْذِرِ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ دِينَارٍ الْخُزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَمْرَو بْنَ الْحَارِثِ الْخُزَاعِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏مَا صُمْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِسْعًا وَعِشْرِينَ أَكْثَرُ مِمَّا صُمْتُ مَعَهُ ثَلَاثِينَ ‏","","",""],[3589,3589,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعْدِ ‏ ‏أَوْ ‏ ‏سَعِيدِ بْنِ عِيَاضٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَحَبَّ ‏ ‏الْعَرْقِ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذِرَاعُ الشَّاةِ وَكَانَ يَرَى أَنَّهُ سُمَّ فِي ذِرَاعِ الشَّاةِ وَكُنَّا نَرَى أَنَّ ‏ ‏الْيَهُودَ ‏ ‏الَّذِينَ سَمُّوهُ ‏","","",""],[3590,3590,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عِيَاضٍ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ ‏ ‏الْبَيَانِ ‏ ‏سِحْرًا قَالَ وَكُنَّا نَرَى أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُمَّ فِي ذِرَاعِ شَاةٍ سَمَّتْهُ ‏ ‏الْيَهُودُ ‏","","",""],[3591,3591,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ سَعِيدٍ الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا وَمَعَهُ قَرِينُهُ مِنْ الْمَلَائِكَةِ وَمِنْ الْجِنِّ قَالُوا وَأَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَأَنَا إِلَّا أَنَّ اللَّهَ أَعَانَنِي عَلَيْهِ فَأَسْلَمَ وَلَا يَأْمُرُنِي إِلَّا بِخَيْرٍ ‏","","",""],[3592,3592,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ الشَّيْبَانِيُّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏زِرَّ بْنَ حُبَيْشٍ ‏ ‏وَعَلَيَّ دَرْبَانِ فَأُلْقِيَتْ عَلَيَّ مَحَبَّةٌ مِنْهُ وَعِنْدَهُ شَبَابٌ فَقَالُوا لِي سَلْهُ ‏ { ‏فَكَانَ ‏ ‏قَابَ ‏ ‏قَوْسَيْنِ أَوْ ‏ ‏أَدْنَى ‏ } ‏فَسَأَلْتُهُ فَقَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَلَهُ سِتُّ مِائَةِ جَنَاحٍ ‏","","",""],[3593,3593,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْمُجَالِدِ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏وَهُوَ يُقْرِئُنَا الْقُرْآنَ فَقَالَ لَهُ رَجُلٌ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏هَلْ سَأَلْتُمْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمْ تَمْلِكُ هَذِهِ الْأُمَّةُ مِنْ خَلِيفَةٍ فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏مَا سَأَلَنِي عَنْهَا أَحَدٌ مُنْذُ قَدِمْتُ ‏ ‏الْعِرَاقَ ‏ ‏قَبْلَكَ ثُمَّ قَالَ نَعَمْ وَلَقَدْ سَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏اثْنَا عَشَرَ كَعِدَّةِ ‏ ‏نُقَبَاءِ ‏ ‏بَنِي إِسْرَائِيلَ ‏","","",""],[3594,3594,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏حَنَشٍ الصَّنْعَانِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ الْجِنِّ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ اللَّهِ ‏ ‏أَمَعَكَ مَاءٌ قَالَ مَعِي ‏ ‏نَبِيذٌ ‏ ‏فِي ‏ ‏إِدَاوَةٍ ‏ ‏فَقَالَ اصْبُبْ عَلَيَّ فَتَوَضَّأَ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏شَرَابٌ وَطَهُورٌ ‏","","",""],[3595,3595,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏وأَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَفْقَتَيْنِ فِي صَفْقَةٍ وَاحِدَةٍ ‏ ‏قَالَ ‏ ‏أَسْوَدُ ‏ ‏قَالَ ‏ ‏شَرِيكٌ ‏ ‏قَالَ ‏ ‏سِمَاكٌ ‏ ‏الرَّجُلُ يَبِيعُ الْبَيْعَ فَيَقُولُ هُوَ ‏ ‏بِنَسَاءٍ ‏ ‏بِكَذَا وَكَذَا وَهُوَ بِنَقْدٍ بِكَذَا وَكَذَا ‏","","",""],[3596,3596,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏ابْنِ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْإِسْلَامَ بَدَأَ ‏ ‏غَرِيبًا ‏ ‏وَسَيَعُودُ ‏ ‏غَرِيبًا ‏ ‏كَمَا بَدَأَ ‏ ‏فَطُوبَى ‏ ‏لِلْغُرَبَاءِ قِيلَ وَمَنْ الْغُرَبَاءُ قَالَ ‏ ‏النُّزَّاعُ ‏ ‏مِنْ الْقَبَائِلِ ‏","","",""],[3597,3597,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَنْبَأَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَجُلًا لَمْ يَعْمَلْ مِنْ الْخَيْرِ شَيْئًا قَطُّ إِلَّا التَّوْحِيدَ فَلَمَّا حَضَرَتْهُ الْوَفَاةُ قَالَ لِأَهْلِهِ إِذَا أَنَا مِتُّ فَخُذُونِي وَاحْرُقُونِي حَتَّى تَدَعُونِي حُمَمَةً ثُمَّ اطْحَنُونِي ثُمَّ ‏ ‏اذْرُونِي ‏ ‏فِي الْبَحْرِ فِي يَوْمٍ ‏ ‏رَاحٍ ‏ ‏قَالَ فَفَعَلُوا بِهِ ذَلِكَ قَالَ فَإِذَا هُوَ فِي قَبْضَةِ اللَّهِ قَالَ فَقَالَ اللَّهُ عَزَّ وَجَلَّ لَهُ ‏ ‏مَا حَمَلَكَ عَلَى مَا صَنَعْتَ قَالَ مَخَافَتُكَ قَالَ فَغَفَرَ اللَّهُ لَهُ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏","","",""],[3598,3598,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْحَكَمِ الْبُنَانِيُّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏وَالْأَسْوَدِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏جَاءَ ابْنَا ‏ ‏مُلَيْكَةَ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَا إِنَّ أُمَّنَا كَانَتْ تُكْرِمُ الزَّوْجَ وَتَعْطِفُ عَلَى الْوَلَدِ قَالَ وَذَكَرَ الضَّيْفَ غَيْرَ أَنَّهَا كَانَتْ وَأَدَتْ فِي الْجَاهِلِيَّةِ قَالَ أُمُّكُمَا فِي النَّارِ فَأَدْبَرَا وَالشَّرُّ يُرَى فِي وُجُوهِهِمَا فَأَمَرَ بِهِمَا فَرُدَّا فَرَجَعَا وَالسُّرُورُ يُرَى فِي وُجُوهِهِمَا رَجِيَا أَنْ يَكُونَ قَدْ حَدَثَ شَيْءٌ فَقَالَ أُمِّي مَعَ أُمِّكُمَا فَقَالَ رَجُلٌ مِنْ الْمُنَافِقِينَ وَمَا يُغْنِي هَذَا عَنْ أُمِّهِ شَيْئًا وَنَحْنُ نَطَأُ ‏ ‏عَقِبَيْهِ ‏ ‏فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَلَمْ أَرَ رَجُلًا قَطُّ أَكْثَرَ سُؤَالًا مِنْهُ يَا رَسُولَ اللَّهِ هَلْ وَعَدَكَ رَبُّكَ فِيهَا ‏ ‏أَوْ فِيهِمَا ‏ ‏قَالَ فَظَنَّ أَنَّهُ مِنْ شَيْءٍ قَدْ سَمِعَهُ فَقَالَ ‏ ‏مَا سَأَلْتُهُ رَبِّي وَمَا أَطْمَعَنِي فِيهِ وَإِنِّي لَأَقُومُ الْمَقَامَ الْمَحْمُودَ يَوْمَ الْقِيَامَةِ فَقَالَ الْأَنْصَارِيُّ وَمَا ذَاكَ الْمَقَامُ الْمَحْمُودُ قَالَ ذَاكَ إِذَا جِيءَ بِكُمْ عُرَاةً حُفَاةً ‏ ‏غُرْلًا ‏ ‏فَيَكُونُ أَوَّلَ مَنْ ‏ ‏يُكْسَى ‏ ‏إِبْرَاهِيمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يَقُولُ اكْسُوا ‏ ‏خَلِيلِي ‏ ‏فَيُؤْتَى بِرَيْطَتَيْنِ بَيْضَاوَيْنِ فَلَيَلْبِسْهُمَا ثُمَّ يَقْعُدُ فَيَسْتَقْبِلُ الْعَرْشَ ثُمَّ أُوتَى بِكِسْوَتِي فَأَلْبَسُهَا فَأَقُومُ عَنْ يَمِينِهِ مَقَامًا لَا يَقُومُهُ أَحَدٌ ‏ ‏غَيْرِي ‏ ‏يَغْبِطُنِي ‏ ‏بِهِ الْأَوَّلُونَ وَالْآخِرُونَ قَالَ وَيُفْتَحُ نَهَرٌ مِنْ الْكَوْثَرِ إِلَى الْحَوْضِ فَقَالَ الْمُنَافِقُونَ فَإِنَّهُ مَا جَرَى مَاءٌ قَطُّ إِلَّا عَلَى ‏ ‏حَالٍ ‏ ‏أَوْ ‏ ‏رَضْرَاضٍ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ عَلَى ‏ ‏حَالٍ ‏ ‏أَوْ ‏ ‏رَضْرَاضٍ ‏ ‏قَالَ حَالُهُ ‏ ‏الْمِسْكُ ‏ ‏وَرَضْرَاضُهُ ‏ ‏التُّومُ ‏ ‏قَالَ الْمُنَافِقُ لَمْ أَسْمَعْ كَالْيَوْمِ قَلَّمَا جَرَى مَاءٌ قَطُّ عَلَى ‏ ‏حَالٍ ‏ ‏أَوْ ‏ ‏رَضْرَاضٍ ‏ ‏إِلَّا كَانَ لَهُ نَبْتَةٌ فَقَالَ الْأَنْصَارِيُّ يَا رَسُولَ اللَّهِ هَلْ لَهُ نَبْتٌ قَالَ نَعَمْ قُضْبَانُ الذَّهَبِ قَالَ الْمُنَافِقُ لَمْ أَسْمَعْ كَالْيَوْمِ فَإِنَّهُ قَلَّمَا نَبَتَ ‏ ‏قَضِيبٌ ‏ ‏إِلَّا أَوْرَقَ وَإِلَّا كَانَ لَهُ ثَمَرٌ قَالَ الْأَنْصَارِيُّ يَا رَسُولَ اللَّهِ هَلْ مِنْ ثَمَرٍ قَالَ نَعَمْ أَلْوَانُ ‏ ‏الْجَوْهَرِ وَمَاؤُهُ أَشَدُّ بَيَاضًا مِنْ اللَّبَنِ وَأَحْلَى مِنْ الْعَسَلِ إِنَّ مَنْ شَرِبَ مِنْهُ مَشْرَبًا لَمْ يَظْمَأْ بَعْدَهُ وَإِنْ حُرِمَهُ لَمْ يُرْوَ بَعْدَهُ ‏","","",""],[3599,3599,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنِي ‏ ‏أَبُو تَمِيمَةَ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏لَعَلَّهُ أَنْ يَكُونَ قَدْ قَالَ ‏ ‏الْبِكَالِيَّ ‏ ‏يُحَدِّثُهُ ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏إِنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏قَالَ ‏ ‏اسْتَبْعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَانْطَلَقْنَا حَتَّى أَتَيْتُ مَكَانَ كَذَا وَكَذَا فَخَطَّ لِي خِطَّةً فَقَالَ لِي كُنْ بَيْنَ ظَهْرَيْ هَذِهِ لَا تَخْرُجْ مِنْهَا فَإِنَّكَ إِنْ خَرَجْتَ هَلَكْتَ قَالَ فَكُنْتُ فِيهَا قَالَ فَمَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَذَفَةً ‏ ‏أَوْ أَبْعَدَ شَيْئًا أَوْ كَمَا قَالَ ‏ ‏ثُمَّ إِنَّهُ ذَكَرَ ‏ ‏هَنِينًا ‏ ‏كَأَنَّهُمْ ‏ ‏الزُّطُّ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏عَفَّانُ ‏ ‏إِنْ شَاءَ اللَّهُ لَيْسَ عَلَيْهِمْ ثِيَابٌ وَلَا أَرَى سَوْآتِهِمْ طِوَالًا قَلِيلٌ لَحْمُهُمْ قَالَ فَأَتَوْا فَجَعَلُوا يَرْكَبُونَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَجَعَلَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ عَلَيْهِمْ قَالَ وَجَعَلُوا يَأْتُونِي فَيُخَيِّلُونَ ‏ ‏أَوْ يَمِيلُونَ ‏ ‏حَوْلِي وَيَعْتَرِضُونَ لِي قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَأُرْعِبْتُ مِنْهُمْ رُعْبًا شَدِيدًا قَالَ فَجَلَسْتُ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏قَالَ فَلَمَّا ‏ ‏انْشَقَّ ‏ ‏عَمُودُ الصُّبْحِ جَعَلُوا يَذْهَبُونَ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏قَالَ ثُمَّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَ ثَقِيلًا وَجِعًا ‏ ‏أَوْ يَكَادُ أَنْ يَكُونَ وَجِعًا ‏ ‏مِمَّا رَكِبُوهُ قَالَ إِنِّي لَأَجِدُنِي ثَقِيلًا ‏ ‏أَوْ كَمَا قَالَ ‏ ‏فَوَضَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ فِي حِجْرِي ‏ ‏أَوْ كَمَا قَالَ ‏ ‏قَالَ ثُمَّ إِنَّ ‏ ‏هَنِينًا ‏ ‏أَتَوْا عَلَيْهِمْ ثِيَابٌ بِيضٌ طِوَالٌ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏وَقَدْ أَغْفَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَأُرْعِبْتُ مِنْهُمْ أَشَدَّ مِمَّا ‏ ‏أُرْعِبْتُ ‏ ‏الْمَرَّةَ الْأُولَى ‏ ‏قَالَ ‏ ‏عَارِمٌ ‏ ‏فِي حَدِيثِهِ قَالَ فَقَالَ بَعْضُهُمْ لِبَعْضٍ ‏ ‏لَقَدْ أُعْطِيَ هَذَا الْعَبْدُ خَيْرًا ‏ ‏أَوْ كَمَا قَالُوا ‏ ‏إِنَّ عَيْنَيْهِ نَائِمَتَانِ ‏ ‏أَوْ قَالَ عَيْنَهُ أَوْ كَمَا قَالُوا ‏ ‏وَقَلْبَهُ يَقْظَانُ ثُمَّ قَالَ ‏ ‏قَالَ ‏ ‏عَارِمٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَ بَعْضُهُمْ لِبَعْضٍ هَلُمَّ فَلْنَضْرِبْ لَهُ مَثَلًا ‏ ‏أَوْ كَمَا قَالُوا ‏ ‏قَالَ بَعْضُهُمْ لِبَعْضٍ ‏ ‏اضْرِبُوا لَهُ مَثَلًا وَنُؤَوِّلُ نَحْنُ أَوْ نَضْرِبُ نَحْنُ وَتُؤَوِّلُونَ أَنْتُمْ فَقَالَ بَعْضُهُمْ لِبَعْضٍ مَثَلُهُ كَمَثَلِ سَيِّدٍ ابْتَنَى بُنْيَانًا حَصِينًا ثُمَّ أَرْسَلَ إِلَى النَّاسِ بِطَعَامٍ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏فَمَنْ لَمْ يَأْتِ طَعَامَهُ ‏ ‏أَوْ قَالَ لَمْ يَتْبَعْهُ ‏ ‏عَذَّبَهُ عَذَابًا شَدِيدًا ‏ ‏أَوْ كَمَا قَالُوا ‏ ‏قَالَ الْآخَرُونَ أَمَّا السَّيِّدُ فَهُوَ رَبُّ الْعَالَمِينَ وَأَمَّا الْبُنْيَانُ فَهُوَ الْإِسْلَامُ وَالطَّعَامُ الْجَنَّةُ وَهُوَ الدَّاعِي فَمَنْ اتَّبَعَهُ كَانَ فِي الْجَنَّةِ ‏ ‏قَالَ ‏ ‏عَارِمٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَوْ كَمَا قَالُوا ‏ ‏وَمَنْ لَمْ يَتَّبِعْهُ عُذِّبَ ‏ ‏أَوْ كَمَا قَالَ ‏ ‏ثُمَّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَيْقَظَ فَقَالَ مَا رَأَيْتَ يَا ‏ ‏ابْنَ أُمِّ عَبْدٍ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏رَأَيْتُ كَذَا وَكَذَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا خَفِيَ عَلَيَّ مِمَّا قَالُوا شَيْءٌ قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُمْ ‏ ‏نَفَرٌ ‏ ‏مِنْ الْمَلَائِكَةِ ‏ ‏أَوْ قَالَ هُمْ مِنْ الْمَلَائِكَةِ أَوْ كَمَا شَاءَ اللَّهُ ‏","","",""],[3600,3600,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُسْلِمٍ الْقَسْمَلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ جَعْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَدْخُلُ النَّارَ مَنْ كَانَ فِي قَلْبِهِ ‏ ‏مِثْقَالُ ‏ ‏حَبَّةٍ مِنْ إِيمَانٍ وَلَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ ‏ ‏مِثْقَالُ ‏ ‏حَبَّةٍ مِنْ كِبْرٍ فَقَالَ ‏ ‏رَجُلٌ ‏ ‏يَا رَسُولَ اللَّهِ إِنِّي لَيُعْجِبُنِي أَنْ يَكُونَ ثَوْبِي غَسِيلًا وَرَأْسِي دَهِينًا ‏ ‏وَشِرَاكُ ‏ ‏نَعْلِي جَدِيدًا وَذَكَرَ أَشْيَاءَ حَتَّى ذَكَرَ عِلَاقَةَ سَوْطِهِ أَفَمِنْ الْكِبْرِ ذَاكَ يَا رَسُولَ اللَّهِ قَالَ لَا ذَاكَ الْجَمَالُ إِنَّ اللَّهَ جَمِيلٌ يُحِبُّ الْجَمَالَ وَلَكِنَّ الْكِبْرَ مَنْ سَفِهَ الْحَقَّ وَازْدَرَى النَّاسَ ‏","","",""]];
